FALSE_FLAG_WORDS = [
    "example","sample","test","testing","smoke","dummy","fake","placeholder","your_flag",
    "flag_here","not_the_flag","notflag","nope","wrong","todo","change_me","insert",
    "project_smoke","tool_ok","smoke_ok"
]
FORMAT_CONTEXT_WORDS = ["format","example","should look","looks like","target flag","flag format","always answer","answer format","template"]

def score_text(s):
    if not s: return 0
    s=str(s)
    if len(s)>18000: s=s[:18000]
    low=s.lower(); score=0
    if "ctf_cs{" in low: score += 240
    if "ctf_cs" in low: score += 150
    if "{" in s and "}" in s: score += 65
    elif "{" in s or "}" in s: score += 25
    for k in ["flag{","ctf{","slapta","raktas","password","key","secret","veliava","token","hidden","decode","cipher","xor","base64","admin","login","answer","winner"]:
        if k in low: score += 24
    sample=s[:12000]
    printable=sum(1 for c in sample if c.isprintable() or c in "\n\r\t")/max(1,len(sample))
    letters=sum(1 for c in sample if c.isalpha())/max(1,len(sample))
    score += min(25,int(printable*25))+min(12,int(letters*12))
    return score

def fast_flag_matches(text, limit=20, scan_limit=9000):
    text=str(text or "")[:scan_limit]
    if "{" not in text or "}" not in text: return []
    low=text.lower(); hits=[]; seen=set()
    for pref in ["ctf_cs","flag","ctf","cyber","sprint"]:
        needle=pref+"{"; start=0
        while len(hits)<limit:
            i=low.find(needle,start)
            if i<0: break
            j=text.find("}",i+len(needle))
            if j<0 or j-i>260:
                start=i+len(needle); continue
            cand=text[i:j+1]
            if cand not in seen and "\n" not in cand and "\r" not in cand:
                seen.add(cand); hits.append(cand)
            start=i+len(needle)
    return hits[:limit]

def extract_flagish_text(text):
    text=str(text or "")[:20000]
    hits=[]; seen=set()
    def add(kind,val,score,why):
        val=str(val)[:900]
        if not val: return
        k=(kind,val)
        if k in seen: return
        seen.add(k); hits.append({"type":kind,"value":val,"score":int(score),"why":why})
    for m in fast_flag_matches(text, limit=60, scan_limit=20000):
        if m.lower().startswith("ctf_cs{"):
            add("exact_ctf_cs",m,300,"Exact target-format candidate.")
        else:
            add("brace_or_flag_fragment",m,120,"Brace/flag-like fragment.")
    low=text.lower(); start=0
    while True:
        i=low.find("ctf_cs{",start)
        if i<0: break
        j=text.find("}",i)
        chunk=text[i:(j+1 if j>i and j-i<260 else min(len(text),i+260))]
        add("partial_ctf_cs",chunk,175,"Partial or full ctf_cs fragment.")
        start=i+7
        if len(hits)>80: break
    for line in text.splitlines()[:1200]:
        ll=line.lower()
        if any(x in ll for x in ["ctf_cs","flag","raktas","slapta","key","secret","token"]) or ("{" in line and "}" in line):
            if len(line)<=900: add("context_line",line,score_text(line),"Useful context line.")
        if len(hits)>=120: break
    return sorted(hits,key=lambda x:x.get("score",0),reverse=True)[:140]

def decode_candidates(text, data=b""):
    outs=[]; seen=set(); text=str(text or "")[:24000]
    def add(t,i,o,base=0):
        if not o: return
        o=str(o)[:9000]
        key=(t,o[:240])
        if key in seen: return
        seen.add(key)
        flags=fast_flag_matches(o, limit=6, scan_limit=9000)
        sc=int(base)+score_text(o)+(100 if flags else 0)
        if sc>=22 or flags:
            outs.append({"type":t,"input":str(i)[:260],"output":o,"flags":flags,"score":sc})
    chunks=re.findall(r"[A-Za-z0-9+/=_-]{8,}|[A-Z2-7=]{8,}|[0-9a-fA-F]{8,}|(?:[01]{8}\s*){2,}|(?:[0-7]{2,3}\s+){2,}[0-7]{2,3}|(?:\d{2,3}[,\s]+){3,}\d{2,3}|(?:[.\-]{1,6}\s+){3,}[.\-]{1,6}",text)[:350]
    for raw in chunks:
        s=raw.strip()
        if len(s)>2000: continue
        try:
            if len(s)<=900 and re.fullmatch(r"[A-Za-z0-9+/=_-]{8,}",s):
                padded=s+"="*((4-len(s)%4)%4)
                add("base64",s,base64.b64decode(padded,validate=False).decode("utf-8","replace"),10)
                if "-" in s or "_" in s: add("base64_urlsafe",s,base64.urlsafe_b64decode(padded).decode("utf-8","replace"),12)
        except Exception: pass
        try:
            if len(s)<=900 and re.fullmatch(r"[A-Z2-7=]{8,}",s): add("base32",s,base64.b32decode(s).decode("utf-8","replace"),8)
        except Exception: pass
        try:
            if len(s)<=180 and re.fullmatch(r"[123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz]{10,}",s):
                b58=try_base58(s)
                if b58 and score_text(b58)>18: add("base58",s,b58,12)
        except Exception: pass
        try:
            h=re.sub(r"\s+","",s)
            if len(h)<=2000 and len(h)%2==0 and re.fullmatch(r"[0-9a-fA-F]{8,}",h):
                add("hex",s,bytes.fromhex(h).decode("utf-8","replace"),10)
        except Exception: pass
        try:
            bits=re.sub(r"\s+","",s)
            if len(bits)<=2048 and len(bits)%8==0 and re.fullmatch(r"[01]{16,}",bits):
                add("binary",s,bytes(int(bits[i:i+8],2) for i in range(0,len(bits),8)).decode("utf-8","replace"),10)
        except Exception: pass
        try:
            parts=s.split()
            if len(parts)>2 and len(parts)<=300 and all(re.fullmatch(r"[0-7]{2,3}",x) for x in parts):
                vals=[int(x,8) for x in parts]
                if all(0 <= v <= 255 for v in vals):
                    add("octal",s,bytes(vals).decode("utf-8","replace"),10)
        except Exception: pass
        try:
            ac=try_ascii_codes(s)
            if ac and score_text(ac)>18: add("ascii_codes",s,ac,14)
        except Exception: pass
        try:
            md=morse_decode(s)
            if md: add("morse",s,md,10)
        except Exception: pass
    visible=text[:9000]
    add("url_decode","visible",urllib.parse.unquote(visible),8)
    add("html_unescape","visible",html.unescape(visible),8)
    if len(visible)<=5000:
        add("atbash","visible",atbash(visible),8)
        add("reverse_text","visible",visible[::-1],8)
    bacon=try_bacon(visible)
    if bacon and score_text(bacon)>18: add("bacon_ab","visible",bacon,15)
    if len(visible)<=2500:
        a="abcdefghijklmnopqrstuvwxyz"; A=a.upper()
        for r in range(1,26):
            add(f"rot{r}","visible",visible.translate(str.maketrans(a+A,a[r:]+a[:r]+A[r:]+A[:r])),6)
    for hit in extract_flagish_text(visible): add(hit["type"],"flag/brace hunter",hit["value"],hit["score"])
    for ctx in expert_context_lines(visible)[:40]: add("context_near_flag_or_brace","context hunter",ctx,18)
    if data:
        outs+=xor_single(data)[:12]+repeating_xor_guesses(data)[:10]+try_decompress_bytes(data)[:8]+xor_crib_ctf_cs(data)[:8]
    return sorted(outs,key=lambda x:x.get("score",0),reverse=True)[:260]

def recursive_decode_seed(text,max_rounds=2):
    text=str(text or "")[:9000]
    results=[]; seen=set(); frontier=[("input",text)]
    for depth in range(max_rounds):
        new=[]
        for label,val in frontier[:12]:
            key=(label,val[:220])
            if key in seen: continue
            seen.add(key)
            for item in decode_candidates(val,b"")[:14]:
                out=(item.get("output","") or "")[:9000]
                item=dict(item); item["output"]=out; item["type"]=f"{label}->{item['type']}"; item["score"]=item.get("score",0)+depth*8
                results.append(item)
                if out and score_text(out)>45 and len(new)<10: new.append((item["type"],out))
        frontier=new[:10]
    return sorted(results,key=lambda x:x.get("score",0),reverse=True)[:80]

def seed_texts(report):
    seeds=[]
    def add(source,text,weight=0,limit=9000):
        text=str(text or "")
        if text.strip(): seeds.append({"source":source,"text":text[:limit],"weight":weight})
    add("file_type",report.get("file",""),5,2000)
    add("strings","\n".join(report.get("strings",[])[:1000]),20,9000)
    for o in report.get("outputs",[])[:80]:
        name=str(o.get("tool","")); txt=o.get("out","") or ""
        if "not installed" in txt.lower(): continue
        limit=4500 if any(x in name.lower() for x in ["strings","xxd","objdump","readelf"]) else 7000
        add("tool:"+name,txt,15,limit)
    for p in report.get("previews",[])[:40]:
        add("preview:"+str(p.get("name","")), (p.get("qr","") or "")+"\n"+(p.get("ocr","") or ""),30+int(p.get("score",0)),5000)
    for ctx in report.get("expert_contexts",[])[:80]: add("context",ctx,40,2000)
    out=[]; seen=set()
    for s in sorted(seeds,key=lambda x:x.get("weight",0),reverse=True):
        k=(s["source"],s["text"][:220])
        if k not in seen: seen.add(k); out.append(s)
    return out[:70]

def chain_decode_report(report,raw=b""):
    chain=[]
    for seed in seed_texts(report)[:55]:
        for item in decode_candidates(seed["text"], raw if seed["source"]=="strings" else b"")[:18]:
            item=dict(item); item["chain_source"]=seed["source"]; item["score"]=item.get("score",0)+seed.get("weight",0); chain.append(item)
        if seed.get("weight",0)>=35 and len(seed.get("text",""))<=3500 and any(x in seed.get("text","").lower() for x in ["ctf","flag","base","xor","rsa","{","}"]):
            for item in recursive_decode_seed(seed["text"])[:8]:
                item=dict(item); item["chain_source"]=seed["source"]+" -> recursive"; item["score"]=item.get("score",0)+seed.get("weight",0)+10; chain.append(item)
    if raw: chain += try_decompress_bytes(raw)[:6]+xor_crib_ctf_cs(raw)[:6]
    out=[]; seen=set()
    for c in sorted(chain,key=lambda x:x.get("score",0),reverse=True):
        k=(c.get("type"),(c.get("output","") or "")[:220])
        if k not in seen: seen.add(k); out.append(c)
    return out[:160]

def internal_tool_result(path, toolname):
    p=Path(path)
    try: data=readbytes(p,4_000_000)
    except Exception as e: return {"tool":toolname,"ok":False,"cmd":"internal:"+toolname,"out":"read failed: "+str(e),"missing":[],"install_hint":"","evidence":[],"decoders":[]}
    strings_list=py_strings(data, limit=3000); text="\n".join(strings_list); out=""
    if toolname=="magic_bytes": out="Magic/head bytes:\n"+data[:160].hex(" ")+"\n\nASCII preview:\n"+data[:800].decode("utf-8","replace")
    elif toolname=="strings": out=text
    elif toolname=="strings_braces":
        lines=[s for s in strings_list if any(k in s.lower() for k in ["ctf_cs","flag","raktas","slapta"]) or "{" in s or "}" in s]
        out="\n".join(f"{i+1}:{line}" for i,line in enumerate(lines[:500]))
    elif toolname=="extract_ascii_context":
        lines=[]
        for i,s in enumerate(strings_list):
            low=s.lower()
            if any(k in low for k in ["ctf_cs","flag","raktas","slapta","key","secret","token","password"]) or "{" in s or "}" in s:
                lines.append("\n".join(strings_list[max(0,i-2):min(len(strings_list),i+3)]))
        out="\n---\n".join(lines[:120])
    elif toolname=="grep_crypto_clues":
        pat=re.compile(r"rsa|aes|xor|base64|base32|base58|md5|sha1|sha256|jwt|nonce|iv|key|secret|n=|e=|c=|p=|q=",re.I)
        out="\n".join(s for s in strings_list if pat.search(s))[:50000]
    elif toolname=="grep_urls_tokens":
        matches=[]
        for s in strings_list:
            matches += re.findall(r"https?://[^\s'\"<>]+|eyJ[A-Za-z0-9_=.-]+|[A-Fa-f0-9]{32,64}",s)
            if len(matches)>500: break
        out="\n".join(matches[:500])
    elif toolname=="strings_utf16":
        try: out="\n".join(re.findall(r"[ -~]{4,}", data.decode("utf-16le","ignore"))[:1200])
        except Exception: out=""
    elif toolname=="hashid_file":
        vals=[]
        for s in strings_list:
            for h in re.findall(r"\b[A-Fa-f0-9]{32}\b|\b[A-Fa-f0-9]{40}\b|\b[A-Fa-f0-9]{64}\b",s):
                vals.append(f"{h} :: "+{32:"possible MD5/NTLM",40:"possible SHA1",64:"possible SHA256"}[len(h)])
        out="\n".join(vals[:500])
    elif toolname=="sha256sum": out=hashlib.sha256(data).hexdigest()+"  "+str(p)
    elif toolname=="md5sum": out=hashlib.md5(data).hexdigest()+"  "+str(p)
    else: return None
    res={"tool":toolname,"ok":True,"cmd":"internal:"+toolname,"out":out[:120000],"missing":[],"install_hint":""}
    res["evidence"]=extract_flagish_text(res["out"])[:60]
    res["decoders"]=decode_candidates(res["out"],b"")[:50]
    return res

def run_tool_local(path,toolname,timeout=180):
    p=Path(path)
    if not p.exists(): return {"tool":toolname,"ok":False,"cmd":"","out":"file not found","missing":[],"install_hint":""}
    internal=internal_tool_result(p,toolname)
    if internal is not None: return internal
    if toolname not in TOOL_COMMANDS: return {"tool":toolname,"ok":False,"cmd":"","out":"unknown tool","missing":[],"install_hint":""}
    try: cmd=TOOL_COMMANDS[toolname](p)
    except Exception as e: return {"tool":toolname,"ok":False,"cmd":"","out":"command build failed: "+str(e),"missing":[],"install_hint":""}
    miss=missing_deps(toolname,cmd)
    if miss:
        hint="Missing dependencies: "+", ".join(miss)+". Run bash FULL_INSTALL.sh."
        return {"tool":toolname,"ok":False,"cmd":" ".join(map(str,cmd)),"out":hint,"missing":miss,"install_hint":hint,"evidence":[],"decoders":[]}
    res=run(cmd,timeout); res["tool"]=toolname; res["missing"]=[]; res["install_hint"]=""
    text=res.get("out","")
    res["evidence"]=extract_flagish_text(text)[:60]
    res["decoders"]=decode_candidates(text,b"")[:50]
    return res

def verifyloop_relevant_tools(path, kind):
    core=["file","magic_bytes","strings","strings_braces","extract_ascii_context","grep_crypto_clues","grep_urls_tokens"]
    by_kind={
        "text": core+["strings_utf16","hashid_file"],
        "generic": core+["strings_utf16","exiftool","binwalk","foremost","yara_basic"],
        "image": core+["exiftool","identify","pngcheck","png_chunks","zbarimg","tesseract","zsteg_all","steghide_info","stegseek","binwalk","binwalk_extract","foremost"],
        "pcap": core+["capinfos","tshark_protocols","tshark_http","tshark_dns","tshark_tcp0","tshark_tcp1","tshark_tcp2","tshark_files"],
        "pdf": core+["pdfinfo","pdftotext","pdfimages","pdfdetach_list","pdfdetach_extract","qpdf_check","exiftool","binwalk"],
        "archive": core+["seven_list","zipinfo","zip_comment","hashid_file","binwalk","binwalk_extract","foremost"],
        "binary": core+["readelf","elf_sections","elf_imports","checksec_basic","rabin2_info","rabin2_strings","r2_info","upx_test","objdump_rodata","nm"],
        "media": core+["ffprobe","soxi","spectrogram","exiftool","binwalk"],
        "sqlite": core+["sqlite_tables","sqlite_schema"],
        "apk": core+["apktool_decode","jadx_decompile"],
        "python_bytecode": core+["python_pyc_decompile","decompyle3"],
    }
    tools=by_kind.get(kind,by_kind["generic"]); out=[]; seen=set()
    for t in tools:
        if t in TOOL_COMMANDS and t not in seen: seen.add(t); out.append(t)
    return out[:45]

def verifyloop_run_tools(pid,path,report,root):
    kind=report.get("kind","generic"); tools=verifyloop_relevant_tools(path,kind); results=[]
    log(pid,f"VerifyLoop: {path.name} kind={kind} auto-tools={len(tools)}")
    slow={"binwalk_extract","foremost","tshark_files","pdfdetach_extract","pdfimages","apktool_decode","jadx_decompile","spectrogram","r2_info","zsteg_all","stegseek"}
    for tool in tools:
        try:
            r=run_tool_local(path,tool,35 if tool in slow else 4)
            r["auto"]=True; r["tool"]="verifyloop:"+tool; results.append(r)
            report.setdefault("commands",[]).append(r.get("cmd",""))
            for ev in r.get("evidence",[]) or []:
                val=ev.get("value","")
                if "ctf_cs{" in val.lower() and val not in report.setdefault("flags",[]): report["flags"].append(val)
            for d in r.get("decoders",[]) or []:
                for f in d.get("flags",[]) or []:
                    if f not in report.setdefault("flags",[]): report["flags"].append(f)
        except Exception as e:
            results.append({"tool":"verifyloop:"+tool,"ok":False,"cmd":tool,"out":"VerifyLoop tool failed: "+str(e),"auto":True})
    added=verifyloop_add_outputs(report,results)
    return {"tools":tools,"added_outputs":len(added),"results":results}

def verifyloop_refresh_analysis(report, raw_data):
    outtxt="\n".join((o.get("out") or "")[:6000] for o in report.get("outputs",[])[:120])
    combined="\n".join(report.get("strings",[])[:1200])+"\n"+outtxt
    report["expert_contexts"]=expert_context_lines(combined)[:100]
    report["decoders"]=sorted(decode_candidates(combined,raw_data)+recursive_decode_seed(combined),key=lambda x:x.get("score",0),reverse=True)[:300]
    report["chain_results"]=chain_decode_report(report,raw_data)
    report["structured_clues"]=detect_structured_clues(combined[:30000]+"\n"+"\n".join((c.get("output","") or "")[:2000] for c in report.get("chain_results",[])[:40]))
    report["hypotheses"]=classify_workflow_hypotheses(report)
    return report

def normalize_flag_candidate(flag):
    flag=str(flag or "").strip()
    m=CTF_CS_RE.search(flag)
    if m: return m.group(0)
    hits=fast_flag_matches(flag,limit=1,scan_limit=400)
    return hits[0] if hits else flag[:300]

def flag_inner(flag):
    m=re.search(r"\{(.*)\}",flag)
    return m.group(1) if m else ""

def is_flag_placeholder(flag,context="",source=""):
    low=(flag+"\n"+context+"\n"+source).lower(); inner=flag_inner(flag).lower(); reasons=[]
    if flag.lower() in ["ctf_cs{...}","ctf_cs{}","ctf_cs{flag}","ctf_cs{your_flag}","ctf_cs{flag_here}"]:
        reasons.append("looks like format/template, not a solved flag")
    if any(w in inner for w in FALSE_FLAG_WORDS): reasons.append("contains placeholder/test/fake wording")
    if any(w in low for w in FORMAT_CONTEXT_WORDS) and ("ctf_cs{...}" in low or "flag format" in low): reasons.append("near format/example wording")
    if len(inner)<3: reasons.append("flag body too short")
    if len(inner)>180: reasons.append("flag body too long")
    if re.fullmatch(r"[.]+",inner or ""): reasons.append("flag body is only dots")
    return reasons

def source_weight(source):
    s=str(source).lower()
    if "raw_bytes" in s or "original_strings" in s: return 85
    if "decoder" in s or "chain" in s: return 75
    if "transform" in s or "transformation_file_scan" in s: return 70
    if "ocr" in s or "qr" in s or "preview" in s: return 68
    if "tool:" in s or "verifyloop:" in s: return 58
    if "agent" in s: return 32
    return 40

def add_flag_source(bucket,flag,source,context="",base=0):
    flag=normalize_flag_candidate(flag)
    if not flag or "{" not in flag or "}" not in flag: return
    key=flag.lower()
    item=bucket.setdefault(key,{"flag":flag,"sources":[],"contexts":[],"score":0,"reasons":[],"negative_reasons":[]})
    item["sources"].append(str(source)[:240])
    if context: item["contexts"].append(str(context)[:900])
    item["score"]+=source_weight(source)+int(base)
    if flag.lower().startswith("ctf_cs{"): item["score"]+=70; item["reasons"].append("matches target ctf_cs{...} format")
    else: item["score"]+=20; item["reasons"].append("flag-like braces but not exact target prefix")
    inner=flag_inner(flag)
    if 6<=len(inner)<=80: item["score"]+=18; item["reasons"].append("reasonable flag body length")
    if re.fullmatch(r"[A-Za-z0-9_!@#$%^&*+\-=:;,.?/|]+",inner or ""): item["score"]+=10; item["reasons"].append("flag body charset looks plausible")
    if any(w in (context or "").lower() for w in ["decoded","decrypted","success","found","output","hidden","secret","raktas","slapta"]):
        item["score"]+=20; item["reasons"].append("supportive solve-context words nearby")
    neg=is_flag_placeholder(flag,context,source)
    if neg: item["negative_reasons"].extend(neg); item["score"]-=120+35*len(neg)

def collect_verified_flags(report):
    bucket={}
    for f in report.get("flags",[])[:80]: add_flag_source(bucket,f,"raw_bytes/original_strings","direct candidate from raw file or previous pipeline",25)
    for s in report.get("strings",[])[:600]:
        for f in fast_flag_matches(s,limit=5,scan_limit=1200): add_flag_source(bucket,f,"original_strings",s[:900],30)
    for o in report.get("outputs",[])[:120]:
        txt=o.get("out","") or ""
        if "not installed" in txt.lower(): continue
        src="tool:"+str(o.get("tool",""))
        for f in fast_flag_matches(txt,limit=15,scan_limit=12000):
            idx=txt.lower().find(f.lower()); ctx=txt[max(0,idx-260):idx+len(f)+260] if idx>=0 else txt[:700]
            add_flag_source(bucket,f,src,ctx,15)
    for d in report.get("decoders",[])[:160]:
        txt=(d.get("output","") or "")[:9000]; src="decoder:"+str(d.get("type",""))
        vals=list(d.get("flags",[]) or [])[:8]+fast_flag_matches(txt,limit=8,scan_limit=9000)
        for f in vals[:12]: add_flag_source(bucket,f,src,txt[:900],int(d.get("score",0)//8))
    for c in report.get("chain_results",[])[:160]:
        txt=(c.get("output","") or "")[:9000]; src="chain:"+str(c.get("type",""))+" from "+str(c.get("chain_source",""))
        vals=list(c.get("flags",[]) or [])[:8]+fast_flag_matches(txt,limit=8,scan_limit=9000)
        for f in vals[:12]: add_flag_source(bucket,f,src,txt[:900],int(c.get("score",0)//7))
    for p in report.get("previews",[])[:40]:
        txt=((p.get("qr","") or "")+"\n"+(p.get("ocr","") or ""))[:9000]; src="preview_ocr_qr:"+str(p.get("name",""))
        vals=list(p.get("flags",[]) or [])[:8]+fast_flag_matches(txt,limit=8,scan_limit=9000)
        for f in vals[:12]: add_flag_source(bucket,f,src,txt[:900],int(p.get("score",0)//6))
    for t in (report.get("transformations",[])+report.get("intermediate_files",[])+report.get("agent_files",[]))[:100]:
        p=Path(t.get("path","")); txt=""
        try:
            if p.exists() and p.is_file() and p.stat().st_size<=700_000:
                if p.suffix.lower() in [".txt",".json",".log",".csv",".xml",".html",".md"] or any(x in p.name.lower() for x in ["decoded","strings","stream","dns","jwt","rsa","hash"]):
                    txt=p.read_text(encoding="utf-8",errors="ignore")[:9000]
        except Exception: txt=""
        if not txt: continue
        src="transform:"+str(t.get("kind",""))+":"+str(t.get("source",""))
        for f in fast_flag_matches(txt,limit=10,scan_limit=9000): add_flag_source(bucket,f,src,txt[:900],int(t.get("score",0)//5))
    verified=[]
    for item in bucket.values():
        item["sources"]=sorted(set(item.get("sources",[])))[:12]
        item["contexts"]=item.get("contexts",[])[:5]
        item["reasons"]=sorted(set(item.get("reasons",[])))[:8]
        item["negative_reasons"]=sorted(set(item.get("negative_reasons",[])))[:8]
        independent=len(set(s.split(":")[0] for s in item["sources"]))
        if independent>=2: item["score"]+=35; item["reasons"].append("seen through multiple evidence families")
        if item["negative_reasons"]: item["status"]="low" if item["score"]<160 else "possible"
        elif item["score"]>=260: item["status"]="confirmed"
        elif item["score"]>=185: item["status"]="likely"
        elif item["score"]>=110: item["status"]="possible"
        else: item["status"]="low"
        verified.append(item)
    return sorted(verified,key=lambda x:x.get("score",0),reverse=True)[:120]

def apply_verified_flags(report):
    verified=collect_verified_flags(report)
    report["verified_flags"]=verified
    report["flags"]=[v["flag"] for v in verified if v.get("status") in ["confirmed","likely"] and not v.get("negative_reasons")]
    return report

def verifyloop_promote_artifacts(root,report):
    if report.get("flags"):
        report["promoted_children"]=[]; return []
    source_path=str(report.get("path",""))
    if "_verifyloop_children" in source_path:
        report["promoted_children"]=[]; return []
    child_dir=root/"files"/"_verifyloop_children"; child_dir.mkdir(parents=True,exist_ok=True)
    promoted=[]; allowed={"decoded","decompress","xor","pcap_exported_object","pcap_tcp_stream","pcap_dns","pdf_text","pdf_attachment","pdf_image","archive_child","binary_unpacked","rsa_params","jwt_candidates","hash_candidates"}
    for item in (report.get("transformations",[])+report.get("intermediate_files",[]))[:100]:
        try:
            src=Path(item.get("path",""))
            if not src.exists() or not src.is_file() or src.stat().st_size<=0 or src.stat().st_size>4_000_000: continue
            kind=item.get("kind",""); score=int(item.get("score",0) or 0); name_low=src.name.lower(); contains=False
            try:
                if src.stat().st_size<=500_000:
                    sample=src.read_text(encoding="utf-8",errors="ignore")[:20000]
                    contains=bool(fast_flag_matches(sample,limit=1) or "ctf_cs" in sample.lower())
            except Exception: contains=False
            useful=kind in allowed or (score>=110 and contains) or any(x in name_low for x in ["decoded","stream","dns","rsa","jwt","xor","decompress","unpacked"])
            noisy=any(x in name_low for x in ["contact_sheet","preview","summary","strings_ascii","strings_utf16"]) and not contains
            if not useful or noisy: continue
            h=hashlib.sha256(src.read_bytes()[:2_000_000]).hexdigest()[:16]
            dest=child_dir/(h+"_"+safe(src.name))
            if not dest.exists(): shutil.copy2(src,dest); promoted.append({"source":str(src),"path":str(dest),"kind":kind,"score":score})
            if len(promoted)>=10: break
        except Exception: pass
    report["promoted_children"]=promoted[:10]
    return promoted[:10]
# ================= end v25 overrides =================


# ==================== v26 StableWorkbench final overrides ====================
NOISE_EVIDENCE_TYPES = {"partial_ctf_cs", "brace_or_flag_fragment", "brace_fragment", "context_line"}
PROMOTED_STATUSES = {"confirmed", "likely"}

def is_noisy_candidate_text(value, why="", typ=""):
    value = str(value or "")
    low = (value + "\n" + str(why) + "\n" + str(typ)).lower()
    if not value.strip():
        return True
    if any(x in low for x in ["ctf_cs{...}", "sample_flag", "dummy", "fake", "placeholder", "example flag", "format is", "flag format", "template"]):
        return True
    if typ in NOISE_EVIDENCE_TYPES and score_text(value) < 95:
        return True
    if len(value) > 2500 and "ctf_cs{" not in low:
        return True
    return False

def stableworkbench_artifacts_for_report(report):
    """Return a clean artifact browser list for one analyzed file."""
    items = []
    def add(kind, obj, source=""):
        if not isinstance(obj, dict):
            return
        path = obj.get("path") or obj.get("source") or ""
        name = obj.get("name") or (Path(path).name if path else kind)
        if not path:
            return
        p = Path(path)
        size = 0
        exists_flag = False
        try:
            exists_flag = p.exists()
            size = p.stat().st_size if exists_flag else 0
        except Exception:
            pass
        items.append({
            "kind": kind,
            "name": name,
            "path": path,
            "url": "/api/raw?path=" + path,
            "source": obj.get("source") or source or obj.get("note") or "",
            "score": int(obj.get("score", 0) or 0),
            "note": obj.get("note",""),
            "exists": exists_flag,
            "size": size,
            "file": report.get("rel","")
        })
    for x in report.get("transformations", [])[:500]:
        add("transformation:" + str(x.get("kind","artifact")), x, "Transform/derived artifact")
    for x in report.get("intermediate_files", [])[:500]:
        add("intermediate", x, "Intermediate generated artifact")
    for x in report.get("agent_files", [])[:200]:
        add("agent_note", x, "Agent note")
    for x in report.get("promoted_children", [])[:200]:
        add("promoted_child", x, "Promoted child artifact")
    for x in report.get("previews", [])[:240]:
        add("preview", x, "Image/media preview")
    # Extracted archive/binwalk folders may be dirs; still expose path for copy.
    for x in report.get("extracted", [])[:80]:
        if isinstance(x, str):
            items.append({
                "kind": "extracted_path",
                "name": Path(x).name,
                "path": x,
                "url": "/api/raw?path=" + x,
                "source": "extract_archive",
                "score": 40,
                "note": "Extraction output path",
                "exists": Path(x).exists(),
                "size": 0,
                "file": report.get("rel","")
            })
    # Deduplicate.
    out, seen = [], set()
    for it in sorted(items, key=lambda x: (x.get("exists", False), x.get("score", 0), x.get("size", 0)), reverse=True):
        k = (it.get("kind"), it.get("path"))
        if k not in seen:
            seen.add(k)
            out.append(it)
    return out[:700]

def stableworkbench_apply_report_postprocess(report, root=None):
    """Noise cleanup + artifact browser + safer promoted flags."""
    try:
        apply_verified_flags(report)
    except Exception:
        pass

    # Never let low/template candidates appear as primary flags.
    good = []
    for v in report.get("verified_flags", []):
        if v.get("status") in PROMOTED_STATUSES and not v.get("negative_reasons"):
            flag = v.get("flag","")
            if not is_noisy_candidate_text(flag, ";".join(v.get("negative_reasons", [])), "verified"):
                good.append(flag)
    report["flags"] = list(dict.fromkeys(good))[:30]

    # Clean findings. Keep verified candidates, strong chains, agent/tool plans, but suppress template noise.
    cleaned = []
    for f in report.get("findings", []):
        val = f.get("value","")
        typ = f.get("type","")
        why = f.get("why","")
        if is_noisy_candidate_text(val, why, typ):
            continue
        if str(typ).startswith("verified_flag_candidate:low"):
            continue
        cleaned.append(f)
    report["findings"] = sorted(cleaned, key=lambda x: x.get("score", 0), reverse=True)[:120]

    report["artifacts"] = stableworkbench_artifacts_for_report(report)
    return report

def project_summary(reports, meta):
    flags=[]; verified_all=[]; kinds={}; evidence=[]; chains=[]; actions=[]; missing=[]; agents=[]; transforms=[]; verifyloops=[]; artifacts=[]
    for r in reports:
        stableworkbench_apply_report_postprocess(r)
        kinds[r.get("kind","?")] = kinds.get(r.get("kind","?"),0)+1

        for v in r.get("verified_flags",[]):
            vv={"file":r.get("rel"),**v}; verified_all.append(vv)
            if v.get("status") in PROMOTED_STATUSES and not v.get("negative_reasons") and not is_noisy_candidate_text(v.get("flag",""), "", "verified"):
                flags.append({"file":r.get("rel"),"flag":v.get("flag"),"score":v.get("score",0),"status":v.get("status")})

        for f in r.get("findings",[])[:80]:
            val=f.get("value","")
            if not is_noisy_candidate_text(val, f.get("why",""), f.get("type","")):
                evidence.append({"file":r.get("rel"),**f})

        for c in r.get("chain_results",[])[:45]:
            out=(c.get("output","") or "")[:900]
            if c.get("score",0)>65 and not is_noisy_candidate_text(out, c.get("type",""), "chain"):
                chains.append({"file":r.get("rel"),"type":c.get("type"),"source":c.get("chain_source"),"score":c.get("score"),"output":out})

        for s in r.get("next_steps",[])[:10]:
            actions.append({"file":r.get("rel"),**s})
        for a in r.get("agent_runs",[])[:15]:
            agents.append({"file":r.get("rel"),"kind":r.get("kind"),**a})
        for t in r.get("transformations",[])[:50]:
            transforms.append({"file":r.get("rel"),**t})
        if r.get("verifyloop"):
            verifyloops.append({"file":r.get("rel"),"kind":r.get("kind"),**r.get("verifyloop",{})})
        for art in r.get("artifacts", [])[:160]:
            artifacts.append(art)
        for o in r.get("outputs",[]):
            if not o.get("ok") and "not installed" in (o.get("out","").lower()):
                missing.append((o.get("out","").split() or ["unknown"])[0])

    verified_all = sorted(verified_all,key=lambda x:x.get("score",0),reverse=True)[:180]
    evidence = sorted(evidence,key=lambda x:x.get("score",0),reverse=True)[:180]
    chains = sorted(chains,key=lambda x:x.get("score",0) or 0,reverse=True)[:120]
    artifacts = sorted(artifacts,key=lambda x:(x.get("exists",False),x.get("score",0),x.get("size",0)),reverse=True)[:500]
    exact=[f for f in flags if "ctf_cs{" in f.get("flag","").lower()]

    workflow=[]
    if exact:
        workflow.append({"priority":100,"step":"Submit/check top verified ctf_cs candidate.","why":"Candidate survived VerifyLoop noise filters and has supporting sources."})
    elif verified_all:
        workflow.append({"priority":92,"step":"Open Verified Flags; inspect possible candidates manually.","why":"Candidates exist, but none were promoted enough for automatic trust."})
    if evidence:
        workflow.append({"priority":90,"step":"Open Evidence Board top item.","why":"Highest scoring non-noisy evidence."})
    if artifacts:
        workflow.append({"priority":88,"step":"Open Artifacts and inspect generated derived files.","why":"All transformed/extracted outputs are collected there."})
    if chains:
        workflow.append({"priority":86,"step":"Open Chain Results for "+chains[0].get("file",""),"why":"Best derived output after noise filtering."})
    if not workflow:
        workflow.append({"priority":50,"step":"Open Files → priority file → Tools/Artifacts.","why":"No strong signal yet."})

    priority=sorted([{
        "file":r.get("rel"),
        "kind":r.get("kind"),
        "flags":len(r.get("flags",[])),
        "verified":len(r.get("verified_flags",[])),
        "artifacts":len(r.get("artifacts",[])),
        "findings":len(r.get("findings",[])),
        "chains":len(r.get("chain_results",[])),
        "top_score":max([x.get("score",0) for x in r.get("findings",[])]+[0])
    } for r in reports],key=lambda x:(x["flags"],x["verified"],x["top_score"],x["artifacts"]),reverse=True)[:120]

    return {
        "flags":flags[:80],
        "verified_flags":verified_all,
        "exact_flags":exact[:80],
        "kinds":kinds,
        "evidence_board":evidence,
        "top_findings":evidence,
        "top_chains":chains,
        "agents":sorted(agents,key=lambda x:x.get("score",0),reverse=True)[:160],
        "transformations":sorted(transforms,key=lambda x:x.get("score",0),reverse=True)[:240],
        "artifacts":artifacts,
        "verifyloops":verifyloops[:160],
        "hypotheses":workflowbrain_project_hypotheses(reports) if "workflowbrain_project_hypotheses" in globals() else [],
        "workflow_steps":sorted(workflow+actions,key=lambda x:x.get("priority",0),reverse=True)[:160],
        "missing_tools":sorted(set(missing))[:100],
        "priority_files":priority
    }

def stableworkbench_limit_tool_output(result):
    """Keep manual tool cards readable and stop UI from choking."""
    if not isinstance(result, dict):
        return result
    out = result.get("out","")
    if isinstance(out, str) and len(out) > 90000:
        result["out"] = out[:90000] + "\n\n[StableWorkbench: output truncated for UI]"
    result["evidence"] = [e for e in result.get("evidence", []) if not is_noisy_candidate_text(e.get("value",""), e.get("why",""), e.get("type",""))][:80]
    result["decoders"] = result.get("decoders", [])[:80]
    return result

# Fast internal implementations for common text tools so user is not kicked into slow terminal waits.
def internal_tool_result(path, toolname):
    p=Path(path)
    try:
        data=readbytes(p, 4_000_000)
    except Exception as e:
        return {"tool":toolname,"ok":False,"cmd":"internal:"+toolname,"out":"read failed: "+str(e),"missing":[],"install_hint":"","evidence":[],"decoders":[]}
    strings_list=py_strings(data, limit=3000)
    out=None
    if toolname=="magic_bytes":
        out="Magic/head bytes:\n"+data[:160].hex(" ")+"\n\nASCII preview:\n"+data[:800].decode("utf-8","replace")
    elif toolname=="strings":
        out="\n".join(strings_list)
    elif toolname=="strings_braces":
        lines=[s for s in strings_list if any(k in s.lower() for k in ["ctf_cs","flag","raktas","slapta"]) or "{" in s or "}" in s]
        out="\n".join(f"{i+1}:{line}" for i,line in enumerate(lines[:500]))
    elif toolname=="extract_ascii_context":
        lines=[]
        for i,s in enumerate(strings_list):
            low=s.lower()
            if any(k in low for k in ["ctf_cs","flag","raktas","slapta","key","secret","token","password"]) or "{" in s or "}" in s:
                ctx=strings_list[max(0,i-2):min(len(strings_list),i+3)]
                lines.append("\n".join(ctx))
        out="\n---\n".join(lines[:120])
    elif toolname=="grep_crypto_clues":
        pat=re.compile(r"rsa|aes|xor|base64|base32|base58|md5|sha1|sha256|jwt|nonce|iv|key|secret|n=|e=|c=|p=|q=", re.I)
        out="\n".join(s for s in strings_list if pat.search(s))[:50000]
    elif toolname=="grep_urls_tokens":
        matches=[]
        for s in strings_list:
            matches += re.findall(r"https?://[^\s'\"<>]+|eyJ[A-Za-z0-9_=.-]+|[A-Fa-f0-9]{32,64}", s)
            if len(matches)>500: break
        out="\n".join(matches[:500])
    elif toolname=="strings_utf16":
        try:
            txt=data.decode("utf-16le","ignore")
            out="\n".join(re.findall(r"[ -~]{4,}", txt)[:1200])
        except Exception:
            out=""
    elif toolname=="hashid_file":
        vals=[]
        for s in strings_list:
            for h in re.findall(r"\b[A-Fa-f0-9]{32}\b|\b[A-Fa-f0-9]{40}\b|\b[A-Fa-f0-9]{64}\b", s):
                typ={32:"possible MD5/NTLM",40:"possible SHA1",64:"possible SHA256"}[len(h)]
                vals.append(f"{h} :: {typ}")
        out="\n".join(vals[:500])
    elif toolname=="sha256sum":
        out=hashlib.sha256(data).hexdigest()+"  "+str(p)
    elif toolname=="md5sum":
        out=hashlib.md5(data).hexdigest()+"  "+str(p)
    else:
        return None
    res={"tool":toolname,"ok":True,"cmd":"internal:"+toolname,"out":out[:120000],"missing":[],"install_hint":""}
    res["evidence"]=extract_flagish_text(res["out"])[:60]
    res["decoders"]=decode_candidates(res["out"], b"")[:50]
    return stableworkbench_limit_tool_output(res)

def run_tool_local(path,toolname,timeout=180):
    p=Path(path)
    if not p.exists():
        return {"tool":toolname,"ok":False,"cmd":"","out":"file not found","missing":[],"install_hint":""}
    internal=internal_tool_result(p,toolname)
    if internal is not None:
        return internal
    if toolname not in TOOL_COMMANDS:
        return {"tool":toolname,"ok":False,"cmd":"","out":"unknown tool","missing":[],"install_hint":""}
    try:
        cmd=TOOL_COMMANDS[toolname](p)
    except Exception as e:
        return {"tool":toolname,"ok":False,"cmd":"","out":"command build failed: "+str(e),"missing":[],"install_hint":""}
    miss=missing_deps(toolname,cmd)
    if miss:
        hint="Missing dependencies: "+", ".join(miss)+". Run bash FULL_INSTALL.sh."
        return {"tool":toolname,"ok":False,"cmd":" ".join(map(str,cmd)),"out":hint,"missing":miss,"install_hint":hint,"evidence":[],"decoders":[]}
    # Manual tool runs get the requested timeout, auto runs use smaller values in verifyloop_run_tools.
    res=run(cmd,timeout)
    res["tool"]=toolname; res["missing"]=[]; res["install_hint"]=""
    text=res.get("out","")
    res["evidence"]=extract_flagish_text(text)[:60]
    res["decoders"]=decode_candidates(text,b"")[:60]
    return stableworkbench_limit_tool_output(res)

def verifyloop_relevant_tools(path, kind):
    """Bounded auto tools. Full manual tools remain available in UI."""
    core=["file","magic_bytes","strings","strings_braces","extract_ascii_context","grep_crypto_clues","grep_urls_tokens"]
    by_kind={
        "text": core+["strings_utf16","hashid_file"],
        "generic": core+["strings_utf16","exiftool","binwalk","foremost","yara_basic"],
        "image": core+["exiftool","identify","pngcheck","png_chunks","zbarimg","tesseract","zsteg_all","steghide_info","stegseek","binwalk","binwalk_extract","foremost"],
        "pcap": core+["capinfos","tshark_protocols","tshark_http","tshark_dns","tshark_tcp0","tshark_tcp1","tshark_tcp2","tshark_files"],
        "pdf": core+["pdfinfo","pdftotext","pdfimages","pdfdetach_list","pdfdetach_extract","qpdf_check","exiftool","binwalk"],
        "archive": core+["seven_list","zipinfo","zip_comment","hashid_file","binwalk","binwalk_extract","foremost"],
        "binary": core+["readelf","elf_sections","elf_imports","checksec_basic","rabin2_info","rabin2_strings","r2_info","upx_test","objdump_rodata","nm"],
        "media": core+["ffprobe","soxi","spectrogram","exiftool","binwalk"],
        "sqlite": core+["sqlite_tables","sqlite_schema"],
        "apk": core+["apktool_decode","jadx_decompile"],
        "python_bytecode": core+["python_pyc_decompile","decompyle3"],
    }
    tools=by_kind.get(kind, by_kind["generic"])
    out=[]; seen=set()
    for t in tools:
        if t in TOOL_COMMANDS and t not in seen:
            seen.add(t); out.append(t)
    return out[:45]

def verifyloop_run_tools(pid, path, report, root):
    kind=report.get("kind","generic")
    tools=verifyloop_relevant_tools(path,kind)
    results=[]
    log(pid,f"StableWorkbench: {path.name} kind={kind} auto-tools={len(tools)}")
    slow={"binwalk_extract","foremost","tshark_files","pdfdetach_extract","pdfimages","apktool_decode","jadx_decompile","spectrogram","r2_info","zsteg_all","stegseek"}
    for tool in tools:
        try:
            timeout=35 if tool in slow else 5
            r=run_tool_local(path,tool,timeout)
            r["auto"]=True
            r["tool"]="stableworkbench:"+tool
            results.append(r)
            report.setdefault("commands",[]).append(r.get("cmd",""))
            for ev in r.get("evidence",[]) or []:
                val=ev.get("value","")
                if "ctf_cs{" in val.lower() and val not in report.setdefault("flags",[]):
                    report["flags"].append(val)
            for d in r.get("decoders",[]) or []:
                for f in d.get("flags",[]) or []:
                    if f not in report.setdefault("flags",[]):
                        report["flags"].append(f)
        except Exception as e:
            results.append({"tool":"stableworkbench:"+tool,"ok":False,"cmd":tool,"out":"StableWorkbench tool failed: "+str(e),"auto":True})
    added=verifyloop_add_outputs(report,results) if "verifyloop_add_outputs" in globals() else []
    return {"tools":tools,"added_outputs":len(added),"results":results}

def analyze_file(pid,path,root,i,total):
    progress(pid,min(94,int((i/max(1,total))*84)+6),f"Analyzing {path.name}")
    data=readbytes(path)
    fileout=run(["file",str(path)],8).get("out","") if exists("file") else ""
    kind=detect_kind(path,fileout)
    ss=py_strings(data)
    rep={"id":uuid.uuid4().hex[:10],"name":path.name,"path":str(path),"rel":str(path.relative_to(root)),"size":path.stat().st_size,"entropy":entropy(data[:2_000_000]),"kind":kind,"file":fileout,"fingerprint":{"sha256":hashlib.sha256(data).hexdigest(),"md5":hashlib.md5(data).hexdigest()},"flags":list(dict.fromkeys(x.decode("utf-8","replace") for x in FLAG_BYTES_RE.findall(data))),"strings":ss[:900],"outputs":[],"previews":[],"commands":[],"extracted":[],"expert_contexts":[],"decoders":[],"chain_results":[],"intermediate_files":[],"findings":[],"next_steps":[],"hypotheses":[],"structured_clues":[],"agent_runs":[],"agent_files":[],"transformations":[],"verifyloop":{},"verified_flags":[],"promoted_children":[],"artifacts":[]}

    if kind=="archive":
        rep["extracted"]=extract_archive(path,root/"files")
    if kind=="image":
        pv,outs=image_lab(path,root)
        rep["previews"]+=pv
        rep["outputs"]+=outs
        for v in pv:
            for f in v.get("flags",[]):
                if f not in rep["flags"]:
                    rep["flags"].append(f)
    if kind=="media" and exists("ffmpeg"):
        spdir=root/"generated"/"media"/path.stem
        spdir.mkdir(parents=True,exist_ok=True)
        sp=spdir/"spectrogram.png"
        r=run(["ffmpeg","-y","-i",str(path),"-lavfi","showspectrumpic=s=1600x900",str(sp)],45)
        rep["outputs"].append({"tool":"spectrogram","ok":r["ok"],"cmd":r["cmd"],"out":r["out"]})
        if sp.exists():
            rep["previews"].append({"name":"spectrogram","url":"/api/raw?path="+str(sp),"path":str(sp),"score":15})

    # Fast initial core pass.
    for label,tpl,to in PIPE["common"]+PIPE.get(kind,[]):
        if label in ["objdump","readelf","r2 quick"] and kind!="binary":
            continue
        cmd=make_cmd(tpl,path)
        rep["commands"].append(" ".join(cmd))
        if cmd[0] not in ["bash","sh"] and not exists(cmd[0]):
            rep["outputs"].append({"tool":label,"ok":False,"cmd":" ".join(cmd),"out":cmd[0]+" not installed"})
            continue
        r=run(cmd,min(to,45))
        rep["outputs"].append({"tool":label,"ok":r["ok"],"cmd":r["cmd"],"out":r["out"]})
        for mf in fast_flag_matches(r.get("out",""), limit=20):
            if mf not in rep["flags"]:
                rep["flags"].append(mf)

    rep["verifyloop"]=verifyloop_run_tools(pid,path,rep,root)
    verifyloop_refresh_analysis(rep,data)
    rep["transformations"]=execute_transform_agents(rep,root,data)
    rep["intermediate_files"]=(rep.get("intermediate_files",[])+rep.get("transformations",[]))[:320]
    write_intermediate_files(rep,root)
    rep["agent_runs"],rep["agent_files"]=run_agent_forge(rep,root)
    rep["intermediate_files"]=(rep.get("intermediate_files",[])+rep.get("agent_files",[]))[:320]
    verifyloop_scan_transform_files(rep)
    verifyloop_refresh_analysis(rep,data)
    apply_verified_flags(rep)
    verifyloop_promote_artifacts(root,rep)
    rep["findings"]=rank_findings(rep)
    rep["next_steps"]=next_steps(rep)
    stableworkbench_apply_report_postprocess(rep,root)
    return rep

def analyze_project(pid):
    root=pdir(pid)
    meta=jread(meta_path(pid),{})
    progress(pid,1,"Preparing project")
    for p in list(all_files(root)):
        try:
            fo=run(["file",str(p)],8).get("out","") if exists("file") else ""
            if detect_kind(p,fo)=="archive":
                extract_archive(p,root/"files")
        except Exception as e:
            log(pid,f"extract error {p.name}: {e}")
    reports=[]
    analyzed=set()
    for pass_no in range(4):
        files=[p for p in all_files(root) if str(p) not in analyzed]
        if not files:
            break
        log(pid,f"StableWorkbench pass {pass_no+1}: {len(files)} files")
        total=max(1,len(files))
        for i,p in enumerate(files,1):
            analyzed.add(str(p))
            try:
                reports.append(analyze_file(pid,p,root,i,total))
            except Exception as e:
                reports.append({"id":uuid.uuid4().hex[:10],"name":p.name,"path":str(p),"rel":str(p.relative_to(root)),"kind":"error","error":str(e),"flags":[],"verified_flags":[],"strings":[],"outputs":[],"previews":[],"commands":[],"decoders":[],"chain_results":[],"intermediate_files":[],"artifacts":[],"findings":[{"score":20,"type":"analysis_error","value":str(e),"why":"File pipeline failed."}],"next_steps":[{"priority":20,"step":"Inspect manually; file pipeline failed.","why":str(e)}]})
            jwrite(report_path(pid),{"project":meta,"files":reports,"summary":project_summary(reports,meta),"ai_prompt":ai_prompt(meta,reports),"updated":now()})
        # Stop extra passes if we already have a promoted verified flag and no new promoted children.
        if any(r.get("flags") for r in reports) and not any(r.get("promoted_children") for r in reports[-total:]):
            break
    progress(pid,98,"Ranking evidence")
    jwrite(report_path(pid),{"project":meta,"files":reports,"summary":project_summary(reports,meta),"ai_prompt":ai_prompt(meta,reports),"updated":now()})
    progress(pid,100,"Done")
    with LOCK:
        JOBS.setdefault(pid,{})["status"]="done"
# ==================== end v26 StableWorkbench final overrides ====================


# ==================== v26 final noise aggregation overrides ====================
def stableworkbench_public_verified(report):
    """Visible verified candidates: no duplicated fake/template spam."""
    out=[]
    seen=set()
    for v in sorted(report.get("verified_flags", []), key=lambda x:x.get("score",0), reverse=True):
        flag=(v.get("flag") or "").strip()
        if not flag:
            continue
        key=flag.lower()
        if key in seen:
            continue
        seen.add(key)
        if v.get("negative_reasons"):
            # Keep only one downgraded candidate if it is still very strong and exact-looking;
            # hide obvious sample/template noise by default.
            if is_noisy_candidate_text(flag, ";".join(v.get("negative_reasons", [])), "verified"):
                continue
            if v.get("score",0) < 220:
                continue
        if v.get("status") == "low":
            continue
        out.append(v)
    return out[:80]

def rank_findings(report):
    fs=[]
    for v in stableworkbench_public_verified(report)[:20]:
        fs.append({"score":v.get("score",0)+80,"type":"verified_flag_candidate:"+v.get("status",""),"value":v.get("flag",""),"why":"; ".join((v.get("reasons",[]) or [])[:3])})
    text="\n".join(report.get("strings",[])[:800])+"\n"+"\n".join((o.get("out") or "")[:8000] for o in report.get("outputs",[]))
    for hit in extract_flagish_text(text):
        if not is_noisy_candidate_text(hit.get("value",""), hit.get("why",""), hit.get("type","")):
            fs.append({"score":hit["score"],"type":hit["type"],"value":hit["value"],"why":hit["why"]})
    for f in report.get("flags",[]):
        if not is_noisy_candidate_text(f,"","promoted"):
            fs.append({"score":360,"type":"promoted_verified_flag","value":f,"why":"Verified likely/confirmed flag candidate."})
    for c in report.get("chain_results",[])[:60]:
        out=(c.get("output","") or "")[:800]
        if c.get("score",0)>70 and not is_noisy_candidate_text(out, c.get("type",""), "chain"):
            fs.append({"score":min(260,c.get("score",0)),"type":"chain:"+str(c.get("type","")),"value":out,"why":"From "+str(c.get("chain_source","unknown"))})
    for a in report.get("agent_runs",[])[:25]:
        fs.append({"score":a.get("score",0),"type":"agent:"+a.get("agent","agent"),"value":a.get("title","")+" :: "+a.get("why",""),"why":"Agent workflow recommendation."})
    for p in report.get("previews",[])[:18]:
        val=f"{p.get('name')} :: {(p.get('qr') or p.get('ocr') or '')[:650]}"
        if (p.get("score",0)>10 or p.get("ocr") or p.get("qr")) and not is_noisy_candidate_text(val,"","preview"):
            fs.append({"score":min(230,p.get("score",0)),"type":"ranked_image_filter","value":val,"why":"OCR/QR over generated filter/bitplane."})
    wf={"image":("image/stego workflow","Preview rank, zsteg, binwalk, OCR/QR, bitplanes.",80),"pcap":("network workflow","HTTP/DNS/TCP streams, exported files, decoders.",80),"binary":("reverse workflow","strings/braces, rabin2/r2, UPX, encoded blobs.",78),"archive":("archive workflow","children/comments/names/password hints.",72),"pdf":("pdf workflow","text/images/attachments/metadata.",72),"media":("media workflow","spectrogram/metadata/reverse audio.",70)}
    if report.get("kind") in wf:
        typ,why,score=wf[report["kind"]]; fs.append({"score":score,"type":typ,"value":report.get("rel"),"why":why})
    out=[]; seen=set()
    for f in sorted(fs,key=lambda x:x.get("score",0),reverse=True):
        k=(f.get("type"),f.get("value","")[:260])
        if k not in seen:
            seen.add(k); out.append(f)
    return out[:100]

def stableworkbench_apply_report_postprocess(report, root=None):
    try:
        apply_verified_flags(report)
    except Exception:
        pass
    good=[]
    for v in report.get("verified_flags", []):
        if v.get("status") in PROMOTED_STATUSES and not v.get("negative_reasons"):
            flag=v.get("flag","")
            if not is_noisy_candidate_text(flag,"","verified"):
                good.append(flag)
    report["flags"]=list(dict.fromkeys(good))[:30]
    report["verified_flags_visible"]=stableworkbench_public_verified(report)
    cleaned=[]
    for f in report.get("findings", []):
        if not is_noisy_candidate_text(f.get("value",""), f.get("why",""), f.get("type","")):
            cleaned.append(f)
    report["findings"]=sorted(cleaned,key=lambda x:x.get("score",0),reverse=True)[:100]
    report["artifacts"]=stableworkbench_artifacts_for_report(report)
    return report

def project_summary(reports, meta):
    flags=[]; verified_map={}; kinds={}; evidence=[]; chains=[]; actions=[]; missing=[]; agents=[]; transforms=[]; verifyloops=[]; artifacts=[]
    for r in reports:
        stableworkbench_apply_report_postprocess(r)
        kinds[r.get("kind","?")]=kinds.get(r.get("kind","?"),0)+1
        for v in r.get("verified_flags_visible", []):
            flag=(v.get("flag") or "").strip()
            if not flag:
                continue
            key=flag.lower()
            vv={"file":r.get("rel"),**v}
            old=verified_map.get(key)
            if old is None or vv.get("score",0)>old.get("score",0):
                verified_map[key]=vv
        for v in r.get("verified_flags", []):
            if v.get("status") in PROMOTED_STATUSES and not v.get("negative_reasons") and not is_noisy_candidate_text(v.get("flag",""),"","verified"):
                flags.append({"file":r.get("rel"),"flag":v.get("flag"),"score":v.get("score",0),"status":v.get("status")})
        for f in r.get("findings",[])[:60]:
            if not is_noisy_candidate_text(f.get("value",""), f.get("why",""), f.get("type","")):
                evidence.append({"file":r.get("rel"),**f})
        for c in r.get("chain_results",[])[:35]:
            out=(c.get("output","") or "")[:900]
            if c.get("score",0)>70 and not is_noisy_candidate_text(out,c.get("type",""),"chain"):
                chains.append({"file":r.get("rel"),"type":c.get("type"),"source":c.get("chain_source"),"score":c.get("score"),"output":out})
        for s in r.get("next_steps",[])[:10]:
            actions.append({"file":r.get("rel"),**s})
        for a in r.get("agent_runs",[])[:12]:
            agents.append({"file":r.get("rel"),"kind":r.get("kind"),**a})
        for t in r.get("transformations",[])[:50]:
            transforms.append({"file":r.get("rel"),**t})
        if r.get("verifyloop"):
            verifyloops.append({"file":r.get("rel"),"kind":r.get("kind"),**r.get("verifyloop",{})})
        for art in r.get("artifacts",[])[:180]:
            artifacts.append(art)
        for o in r.get("outputs",[]):
            if not o.get("ok") and "not installed" in (o.get("out","").lower()):
                missing.append((o.get("out","").split() or ["unknown"])[0])

    # Deduplicate promoted flags by flag string.
    flag_map={}
    for f in flags:
        key=(f.get("flag") or "").lower()
        if key and (key not in flag_map or f.get("score",0)>flag_map[key].get("score",0)):
            flag_map[key]=f
    flags=sorted(flag_map.values(),key=lambda x:x.get("score",0),reverse=True)[:60]
    verified_all=sorted(verified_map.values(),key=lambda x:x.get("score",0),reverse=True)[:100]
    evidence=sorted(evidence,key=lambda x:x.get("score",0),reverse=True)[:120]
    chains=sorted(chains,key=lambda x:x.get("score",0) or 0,reverse=True)[:90]
    artifacts=sorted(artifacts,key=lambda x:(x.get("exists",False),x.get("score",0),x.get("size",0)),reverse=True)[:650]
    exact=[f for f in flags if "ctf_cs{" in f.get("flag","").lower()]
    workflow=[]
    if exact:
        workflow.append({"priority":100,"step":"Submit/check top verified ctf_cs candidate.","why":"Candidate survived noise filters and has supporting sources."})
    elif verified_all:
        workflow.append({"priority":92,"step":"Open Verified Flags; inspect possible candidates manually.","why":"Candidates exist, but none were promoted enough for automatic trust."})
    if artifacts:
        workflow.append({"priority":90,"step":"Open Artifacts browser.","why":"All generated/transformed/extracted files are collected with open/copy controls."})
    if evidence:
        workflow.append({"priority":88,"step":"Open Evidence Board top item.","why":"Noisy template/sample candidates are hidden."})
    if chains:
        workflow.append({"priority":84,"step":"Open Chain Results for "+chains[0].get("file",""),"why":"Best derived output after noise filtering."})
    if not workflow:
        workflow.append({"priority":50,"step":"Open Files → priority file → Artifacts/Tools.","why":"No strong signal yet."})
    priority=sorted([{"file":r.get("rel"),"kind":r.get("kind"),"flags":len(r.get("flags",[])),"verified":len(r.get("verified_flags_visible",[])),"artifacts":len(r.get("artifacts",[])),"findings":len(r.get("findings",[])),"chains":len(r.get("chain_results",[])),"top_score":max([x.get("score",0) for x in r.get("findings",[])]+[0])} for r in reports],key=lambda x:(x["flags"],x["verified"],x["top_score"],x["artifacts"]),reverse=True)[:120]
    return {"flags":flags,"verified_flags":verified_all,"exact_flags":exact,"kinds":kinds,"evidence_board":evidence,"top_findings":evidence,"top_chains":chains,"agents":sorted(agents,key=lambda x:x.get("score",0),reverse=True)[:160],"transformations":sorted(transforms,key=lambda x:x.get("score",0),reverse=True)[:240],"artifacts":artifacts,"verifyloops":verifyloops[:160],"hypotheses":workflowbrain_project_hypotheses(reports) if "workflowbrain_project_hypotheses" in globals() else [],"workflow_steps":sorted(workflow+actions,key=lambda x:x.get("priority",0),reverse=True)[:160],"missing_tools":sorted(set(missing))[:100],"priority_files":priority}
# ==================== end v26 final noise aggregation overrides ====================


# ==================== v27 SmartSolve final layer ====================
SMARTSOLVE_NOISE_WORDS = set(FALSE_FLAG_WORDS + ["sample_test", "sample", "example", "template", "dummy_test", "smoke", "format"])

def smartsolve_clean_verified_list(report):
    """Ultra-visible list: only real-looking candidates, deduped hard."""
    out, seen = [], set()
    for v in sorted(report.get("verified_flags", []), key=lambda x:x.get("score",0), reverse=True):
        flag = (v.get("flag") or "").strip()
        if not flag:
            continue
        low = flag.lower()
        inner = flag_inner(flag).lower()
        if low in seen:
            continue
        seen.add(low)
        if any(w in inner for w in SMARTSOLVE_NOISE_WORDS):
            continue
        if v.get("negative_reasons"):
            continue
        if v.get("status") not in ["confirmed", "likely"]:
            continue
        if not low.startswith("ctf_cs{"):
            continue
        out.append(v)
    return out[:25]

def smartsolve_candidate_health(report):
    total = len(report.get("verified_flags", []))
    visible = len(smartsolve_clean_verified_list(report))
    negatives = sum(1 for v in report.get("verified_flags", []) if v.get("negative_reasons"))
    promoted = len(report.get("flags", []))
    return {
        "total_raw_candidates": total,
        "visible_verified_candidates": visible,
        "negative_or_noisy_candidates": negatives,
        "promoted_flags": promoted,
        "noise_ratio": round(negatives / max(1, total), 3)
    }

def smartsolve_make_brief(root, report):
    """Create a concise solver brief artifact for humans/local AI."""
    outdir = root / "generated" / "smartsolve_briefs"
    outdir.mkdir(parents=True, exist_ok=True)
    brief = {
        "file": report.get("rel"),
        "kind": report.get("kind"),
        "promoted_flags": report.get("flags", []),
        "verified_candidates": smartsolve_clean_verified_list(report),
        "candidate_health": smartsolve_candidate_health(report),
        "top_findings": report.get("findings", [])[:12],
        "top_chains": report.get("chain_results", [])[:10],
        "top_artifacts": report.get("artifacts", [])[:30],
        "recipes": report.get("recipe_runs", [])[:12],
        "next_steps": report.get("next_steps", [])[:12],
    }
    p = outdir / (safe(report.get("name","file")) + ".smartsolve.json")
    try:
        p.write_text(json.dumps(brief, ensure_ascii=False, indent=2), encoding="utf-8")
        return {"kind":"solver_brief","name":p.name,"path":str(p),"url":"/api/raw?path="+str(p),"source":"SmartSolve brief","score":95,"note":"Concise solve summary for human/local AI","exists":True,"size":p.stat().st_size,"file":report.get("rel","")}
    except Exception:
        return None

def smartsolve_artifact_graph(report):
    """Small artifact graph so the user can see where files came from."""
    nodes = []
    edges = []
    seen = set()
    def node(node_id, label, kind, path="", score=0):
        if node_id in seen:
            return
        seen.add(node_id)
        nodes.append({"id":node_id,"label":label,"kind":kind,"path":path,"score":score})
    root_id = "file:" + report.get("rel","root")
    node(root_id, report.get("rel","file"), "original", report.get("path",""), 100)
    for i,a in enumerate(report.get("artifacts", [])[:160]):
        aid = "artifact:" + str(i) + ":" + a.get("path","")
        node(aid, a.get("name") or Path(a.get("path","")).name, a.get("kind","artifact"), a.get("path",""), a.get("score",0))
        edges.append({"from":root_id,"to":aid,"label":a.get("source","generated")})
    for i,c in enumerate(report.get("chain_results", [])[:30]):
        cid = "chain:" + str(i)
        node(cid, c.get("type","chain"), "chain", "", c.get("score",0))
        edges.append({"from":root_id,"to":cid,"label":c.get("chain_source","decoder")})
    return {"nodes":nodes[:180],"edges":edges[:220]}

def smartsolve_recipe_engine(report, root):
    """Recipe ranking based on real CTF solve patterns."""
    recipes=[]
    kind = report.get("kind","generic")
    text = "\n".join(report.get("strings",[])[:900]) + "\n" + "\n".join((o.get("out") or "")[:4000] for o in report.get("outputs",[])[:30])
    low = text.lower()
    def add(name, score, why, actions, artifact_kinds=None):
        arts = []
        for a in report.get("artifacts", [])[:200]:
            if not artifact_kinds or any(k in a.get("kind","") for k in artifact_kinds):
                arts.append(a)
        recipes.append({"name":name,"score":int(score),"why":why,"actions":actions,"artifacts":arts[:20]})
    if kind == "image":
        add("image_lsb_visual", 90, "Image challenge: filters/bitplanes/LSB/OCR/QR are high-value first.", ["Open Artifacts → preview/contact sheet", "Open Preview top tiles", "Check LSB decoded text", "Run zsteg_all if installed"], ["preview","image","decoded"])
        if "zip" in low or "archive" in low or "binwalk" in low:
            add("image_payload", 86, "Image output suggests embedded or appended payload.", ["Open Artifacts → archive_child/promoted_child", "Run binwalk_extract/foremost manually if needed"], ["archive","promoted","transformation"])
    elif kind == "pcap":
        add("pcap_exfil", 92, "PCAP solve path: protocol stats, HTTP objects, DNS labels, TCP streams.", ["Open Artifacts → pcap_tcp_stream/pcap_dns/pcap_exported_object", "Open Chain results from streams", "Decode suspicious labels"], ["pcap"])
    elif kind == "binary":
        add("binary_string_decrypt", 90, "Reverse task: string/rodata/imports often reveal encoded constants or validation logic.", ["Open Artifacts → binary_dump", "Open Chain top results", "Run rabin2_strings/r2_info manually if available"], ["binary","decoded","xor"])
        if "upx" in low or "packed" in low:
            add("binary_unpack", 88, "Packing/UPX indicator present.", ["Open UPX artifacts/logs", "Analyze unpacked child if created"], ["unpacked"])
    elif kind in ["text","generic"]:
        if any(x in low for x in ["rsa","n=","e=","c="]):
            add("crypto_rsa_params", 88, "RSA-like parameters detected.", ["Open Artifacts → rsa_parameters.json", "Ask local AI for attack classification", "Use local RsaCtfTool manually if installed"], ["rsa"])
        if any(x in low for x in ["eyj", "jwt"]):
            add("jwt_decode", 82, "JWT-like token detected.", ["Open JWT artifacts", "Decode header/payload", "Check alg/claims"], ["jwt"])
        add("crypto_encoding_stack", 84, "Text/generic task: recursive encoding/XOR/decompression stack likely.", ["Open Chain", "Open decoded/xor artifacts", "Use Decoder Lab on top blob"], ["decoded","xor","blob","decompress"])
    elif kind == "pdf":
        add("pdf_layers", 88, "PDF tasks often hide flags in text layer, attachments, images, or metadata.", ["Open PDF artifacts", "Inspect attachments/images", "Run OCR on extracted images"], ["pdf"])
    elif kind == "archive":
        add("archive_nested", 88, "Archive tasks often use nested files, comments, child artifacts, or password hints.", ["Open archive_child artifacts", "Inspect comments/listing", "Analyze child files"], ["archive","promoted"])
    elif kind == "media":
        add("media_signal", 84, "Media tasks often use metadata, spectrograms, or appended data.", ["Open spectrogram artifact", "Inspect strings/binwalk artifacts", "Decode any text"], ["media","preview"])
    elif kind in ["sqlite","apk","python_bytecode"]:
        add("structured_artifact", 84, "Structured artifact should be decompiled/queried and searched for constants.", ["Open schema/decompile artifacts", "Search generated files", "Check Chain"], ["decoded","strings","artifact"])
    if report.get("flags"):
        add("verified_submit", 100, "A promoted verified flag exists.", ["Copy promoted flag from Summary/Verified Flags", "Check if challenge accepts it"], [])
    if not recipes:
        add("generic_triage", 55, "No strong recipe matched; use artifacts and chain first.", ["Open Artifacts", "Open Chain", "Run manual Deep Suite"], [])
    return sorted(recipes, key=lambda x:x.get("score",0), reverse=True)[:18]

def smartsolve_postprocess(report, root=None):
    if root is None:
        root = BASE
    stableworkbench_apply_report_postprocess(report, root)
    report["verified_flags_visible"] = smartsolve_clean_verified_list(report)
    report["candidate_health"] = smartsolve_candidate_health(report)
    report["recipe_runs"] = smartsolve_recipe_engine(report, root)
    brief = smartsolve_make_brief(root, report)
    if brief:
        report.setdefault("artifacts", [])
        if not any(a.get("path") == brief["path"] for a in report["artifacts"]):
            report["artifacts"].insert(0, brief)
    report["artifact_graph"] = smartsolve_artifact_graph(report)
    # Re-clean findings after recipe/brief addition.
    cleaned = []
    for f in report.get("findings", []):
        if not is_noisy_candidate_text(f.get("value",""), f.get("why",""), f.get("type","")):
            cleaned.append(f)
    report["findings"] = sorted(cleaned, key=lambda x:x.get("score",0), reverse=True)[:90]
    return report

def analyze_file(pid,path,root,i,total):
    progress(pid,min(94,int((i/max(1,total))*84)+6),f"Analyzing {path.name}")
    data=readbytes(path)
    fileout=run(["file",str(path)],8).get("out","") if exists("file") else ""
    kind=detect_kind(path,fileout)
    ss=py_strings(data)
    rep={"id":uuid.uuid4().hex[:10],"name":path.name,"path":str(path),"rel":str(path.relative_to(root)),"size":path.stat().st_size,"entropy":entropy(data[:2_000_000]),"kind":kind,"file":fileout,"fingerprint":{"sha256":hashlib.sha256(data).hexdigest(),"md5":hashlib.md5(data).hexdigest()},"flags":list(dict.fromkeys(x.decode("utf-8","replace") for x in FLAG_BYTES_RE.findall(data))),"strings":ss[:900],"outputs":[],"previews":[],"commands":[],"extracted":[],"expert_contexts":[],"decoders":[],"chain_results":[],"intermediate_files":[],"findings":[],"next_steps":[],"hypotheses":[],"structured_clues":[],"agent_runs":[],"agent_files":[],"transformations":[],"verifyloop":{},"verified_flags":[],"promoted_children":[],"artifacts":[],"recipe_runs":[],"artifact_graph":{},"candidate_health":{}}
    if kind=="archive":
        rep["extracted"]=extract_archive(path,root/"files")
    if kind=="image":
        pv,outs=image_lab(path,root)
        rep["previews"]+=pv
        rep["outputs"]+=outs
        for v in pv:
            for f in v.get("flags",[]):
                if f not in rep["flags"]:
                    rep["flags"].append(f)
    if kind=="media" and exists("ffmpeg"):
        spdir=root/"generated"/"media"/path.stem
        spdir.mkdir(parents=True,exist_ok=True)
        sp=spdir/"spectrogram.png"
        r=run(["ffmpeg","-y","-i",str(path),"-lavfi","showspectrumpic=s=1600x900",str(sp)],45)
        rep["outputs"].append({"tool":"spectrogram","ok":r["ok"],"cmd":r["cmd"],"out":r["out"]})
        if sp.exists():
            rep["previews"].append({"name":"spectrogram","url":"/api/raw?path="+str(sp),"path":str(sp),"score":15})
    for label,tpl,to in PIPE["common"]+PIPE.get(kind,[]):
        if label in ["objdump","readelf","r2 quick"] and kind!="binary":
            continue
        cmd=make_cmd(tpl,path)
        rep["commands"].append(" ".join(cmd))
        if cmd[0] not in ["bash","sh"] and not exists(cmd[0]):
            rep["outputs"].append({"tool":label,"ok":False,"cmd":" ".join(cmd),"out":cmd[0]+" not installed"})
            continue
        r=run(cmd,min(to,45))
        rep["outputs"].append({"tool":label,"ok":r["ok"],"cmd":r["cmd"],"out":r["out"]})
        for mf in fast_flag_matches(r.get("out",""), limit=20):
            if mf not in rep["flags"]:
                rep["flags"].append(mf)
    rep["verifyloop"]=verifyloop_run_tools(pid,path,rep,root)
    verifyloop_refresh_analysis(rep,data)
    rep["transformations"]=execute_transform_agents(rep,root,data)
    rep["intermediate_files"]=(rep.get("intermediate_files",[])+rep.get("transformations",[]))[:320]
    write_intermediate_files(rep,root)
    rep["agent_runs"],rep["agent_files"]=run_agent_forge(rep,root)
    rep["intermediate_files"]=(rep.get("intermediate_files",[])+rep.get("agent_files",[]))[:320]
    verifyloop_scan_transform_files(rep)
    verifyloop_refresh_analysis(rep,data)
    apply_verified_flags(rep)
    verifyloop_promote_artifacts(root,rep)
    rep["findings"]=rank_findings(rep)
    rep["next_steps"]=next_steps(rep)
    smartsolve_postprocess(rep,root)
    return rep

def project_summary(reports, meta):
    flags=[]; verified_map={}; kinds={}; evidence=[]; chains=[]; actions=[]; missing=[]; agents=[]; transforms=[]; verifyloops=[]; artifacts=[]; recipes=[]; graphs=[]
    for r in reports:
        stableworkbench_apply_report_postprocess(r)
        kinds[r.get("kind","?")]=kinds.get(r.get("kind","?"),0)+1
        for v in r.get("verified_flags_visible", []):
            key=(v.get("flag") or "").lower()
            vv={"file":r.get("rel"),**v}
            if key and (key not in verified_map or vv.get("score",0)>verified_map[key].get("score",0)):
                verified_map[key]=vv
        for f in r.get("flags", []):
            if not is_noisy_candidate_text(f,"","promoted"):
                flags.append({"file":r.get("rel"),"flag":f,"score":999,"status":"promoted"})
        for f in r.get("findings",[])[:60]:
            if not is_noisy_candidate_text(f.get("value",""), f.get("why",""), f.get("type","")):
                evidence.append({"file":r.get("rel"),**f})
        for c in r.get("chain_results",[])[:30]:
            out=(c.get("output","") or "")[:900]
            if c.get("score",0)>70 and not is_noisy_candidate_text(out,c.get("type",""),"chain"):
                chains.append({"file":r.get("rel"),"type":c.get("type"),"source":c.get("chain_source"),"score":c.get("score"),"output":out})
        for s in r.get("next_steps",[])[:10]:
            actions.append({"file":r.get("rel"),**s})
        for a in r.get("agent_runs",[])[:12]:
            agents.append({"file":r.get("rel"),"kind":r.get("kind"),**a})
        for t in r.get("transformations",[])[:50]:
            transforms.append({"file":r.get("rel"),**t})
        if r.get("verifyloop"):
            verifyloops.append({"file":r.get("rel"),"kind":r.get("kind"),**r.get("verifyloop",{})})
        for art in r.get("artifacts",[])[:220]:
            artifacts.append(art)
        for rec in r.get("recipe_runs",[])[:12]:
            recipes.append({"file":r.get("rel"),"kind":r.get("kind"),**rec})
        if r.get("artifact_graph"):
            graphs.append({"file":r.get("rel"),"graph":r.get("artifact_graph")})
        for o in r.get("outputs",[]):
            if not o.get("ok") and "not installed" in (o.get("out","").lower()):
                missing.append((o.get("out","").split() or ["unknown"])[0])
    # Dedupe flags.
    flag_map={}
    for f in flags:
        key=(f.get("flag") or "").lower()
        if key and (key not in flag_map or f.get("score",0)>flag_map[key].get("score",0)):
            flag_map[key]=f
    flags=sorted(flag_map.values(),key=lambda x:x.get("score",0),reverse=True)[:60]
    verified_all=sorted(verified_map.values(),key=lambda x:x.get("score",0),reverse=True)[:80]
    evidence=sorted(evidence,key=lambda x:x.get("score",0),reverse=True)[:120]
    chains=sorted(chains,key=lambda x:x.get("score",0) or 0,reverse=True)[:90]
    artifacts=sorted(artifacts,key=lambda x:(x.get("exists",False),x.get("score",0),x.get("size",0)),reverse=True)[:700]
    recipes=sorted(recipes,key=lambda x:x.get("score",0),reverse=True)[:140]
    exact=[f for f in flags if "ctf_cs{" in f.get("flag","").lower()]
    workflow=[]
    if exact:
        workflow.append({"priority":100,"step":"Submit/check top SmartSolve verified flag.","why":"Candidate survived noise filters and recipe verification."})
    elif verified_all:
        workflow.append({"priority":92,"step":"Open Verified Flags; inspect likely candidates.","why":"Candidates exist, but none were promoted enough for automatic trust."})
    if recipes:
        workflow.append({"priority":91,"step":"Open Recipes tab and follow top recipe.","why":"Recipe Engine picked solve paths from artifact/tool signals."})
    if artifacts:
        workflow.append({"priority":90,"step":"Open Artifacts browser.","why":"Generated/transformed/extracted files are collected with open/copy controls."})
    if evidence:
        workflow.append({"priority":88,"step":"Open Evidence Board top item.","why":"Noisy template/sample candidates are hidden."})
    if not workflow:
        workflow.append({"priority":50,"step":"Open Files → priority file → Artifacts/Tools.","why":"No strong signal yet."})
    priority=sorted([{"file":r.get("rel"),"kind":r.get("kind"),"flags":len(r.get("flags",[])),"verified":len(r.get("verified_flags_visible",[])),"recipes":len(r.get("recipe_runs",[])),"artifacts":len(r.get("artifacts",[])),"findings":len(r.get("findings",[])),"chains":len(r.get("chain_results",[])),"top_score":max([x.get("score",0) for x in r.get("findings",[])]+[0])} for r in reports],key=lambda x:(x["flags"],x["verified"],x["recipes"],x["top_score"],x["artifacts"]),reverse=True)[:120]
    return {"flags":flags,"verified_flags":verified_all,"exact_flags":exact,"kinds":kinds,"evidence_board":evidence,"top_findings":evidence,"top_chains":chains,"agents":sorted(agents,key=lambda x:x.get("score",0),reverse=True)[:160],"transformations":sorted(transforms,key=lambda x:x.get("score",0),reverse=True)[:240],"artifacts":artifacts,"recipes":recipes,"artifact_graphs":graphs[:120],"verifyloops":verifyloops[:160],"hypotheses":workflowbrain_project_hypotheses(reports) if "workflowbrain_project_hypotheses" in globals() else [],"workflow_steps":sorted(workflow+actions,key=lambda x:x.get("priority",0),reverse=True)[:160],"missing_tools":sorted(set(missing))[:100],"priority_files":priority}

@app.post("/api/run_recipe")
async def run_recipe_endpoint(path:str=Form(...)):
    p=Path(path)
    if not p.exists():
        return {"ok":False,"error":"file not found"}
    try:
        data=readbytes(p)
        fileout=run(["file",str(p)],8).get("out","") if exists("file") else ""
        kind=detect_kind(p,fileout)
        ss=py_strings(data)
        temp={"id":"manual","name":p.name,"path":str(p),"rel":p.name,"size":p.stat().st_size,"entropy":entropy(data[:2_000_000]),"kind":kind,"file":fileout,"fingerprint":{"sha256":hashlib.sha256(data).hexdigest(),"md5":hashlib.md5(data).hexdigest()},"flags":[],"strings":ss[:900],"outputs":[],"previews":[],"commands":[],"extracted":[],"expert_contexts":[],"decoders":[],"chain_results":[],"intermediate_files":[],"findings":[],"next_steps":[],"hypotheses":[],"structured_clues":[],"agent_runs":[],"agent_files":[],"transformations":[],"verifyloop":{},"verified_flags":[],"promoted_children":[],"artifacts":[],"recipe_runs":[],"artifact_graph":{},"candidate_health":{}}
        if kind=="image":
            pv,outs=image_lab(p,p.parent)
            temp["previews"]+=pv; temp["outputs"]+=outs
        temp["verifyloop"]=verifyloop_run_tools("manual",p,temp,p.parent)
        verifyloop_refresh_analysis(temp,data)
        temp["transformations"]=execute_transform_agents(temp,p.parent,data)
        temp["intermediate_files"]=(temp.get("intermediate_files",[])+temp.get("transformations",[]))[:320]
        temp["agent_runs"],temp["agent_files"]=run_agent_forge(temp,p.parent)
        verifyloop_scan_transform_files(temp)
        verifyloop_refresh_analysis(temp,data)
        apply_verified_flags(temp)
        temp["findings"]=rank_findings(temp)
        temp["next_steps"]=next_steps(temp)
        smartsolve_postprocess(temp,p.parent)
        return {"ok":True,"kind":kind,"recipes":temp.get("recipe_runs",[]),"flags":temp.get("flags",[]),"verified_flags":temp.get("verified_flags_visible",[]),"artifacts":temp.get("artifacts",[])[:220],"artifact_graph":temp.get("artifact_graph",{}),"findings":temp.get("findings",[])[:80]}
    except Exception as e:
        return {"ok":False,"error":str(e)}
# ==================== end v27 SmartSolve final layer ====================


# ==================== v27 strict target flag promotion override ====================
def smartsolve_strict_target_flag_ok(flag, meta=None):
    """Promote only clean, plausible final target flags. Weird decode noise stays in chain/artifacts, not Summary."""
    flag = str(flag or "").strip()
    if not flag.lower().startswith("ctf_cs{") or not flag.endswith("}"):
        return False
    if "\n" in flag or "\r" in flag or "\t" in flag:
        return False
    if "�" in flag:
        return False
    inner = flag_inner(flag)
    low_inner = inner.lower()
    if len(inner) < 6 or len(inner) > 96:
        return False
    if any(ord(c) < 32 or ord(c) > 126 for c in inner):
        return False
    if any(w in low_inner for w in SMARTSOLVE_NOISE_WORDS):
        return False
    if "ctf_cs" in low_inner or "flag{" in low_inner:
        return False
    # Strict display-safe flag body: words/digits/underscore/dash/dot/colon only.
    # Other symbol-heavy decodes are kept in Chain, not promoted.
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_\-:.]{5,95}", inner):
        return False
    # Avoid very random short mixed fragments without separators.
    if len(inner) < 10 and "_" not in inner and "-" not in inner and "." not in inner and ":" not in inner:
        return False
    return True

def smartsolve_clean_verified_list(report):
    out, seen = [], set()
    for v in sorted(report.get("verified_flags", []), key=lambda x:x.get("score",0), reverse=True):
        flag = (v.get("flag") or "").strip()
        key = flag.lower()
        if not flag or key in seen:
            continue
        seen.add(key)
        if not smartsolve_strict_target_flag_ok(flag, v):
            continue
        if v.get("negative_reasons"):
            continue
        if v.get("status") not in ["confirmed", "likely"]:
            continue
        out.append(v)
    return out[:25]

def stableworkbench_apply_report_postprocess(report, root=None):
    try:
        apply_verified_flags(report)
    except Exception:
        pass
    good=[]
    for v in report.get("verified_flags", []):
        flag=v.get("flag","")
        if v.get("status") in PROMOTED_STATUSES and not v.get("negative_reasons") and smartsolve_strict_target_flag_ok(flag, v):
            good.append(flag)
    report["flags"]=list(dict.fromkeys(good))[:30]
    report["verified_flags_visible"]=smartsolve_clean_verified_list(report)
    cleaned=[]
    for f in report.get("findings", []):
        val=f.get("value","")
        typ=f.get("type","")
        # Hide any exact-looking but strict-invalid ctf_cs candidate from front evidence.
        if str(val).lower().startswith("ctf_cs{") and not smartsolve_strict_target_flag_ok(val):
            continue
        if not is_noisy_candidate_text(val, f.get("why",""), typ):
            cleaned.append(f)
    report["findings"]=sorted(cleaned,key=lambda x:x.get("score",0),reverse=True)[:90]
    report["artifacts"]=stableworkbench_artifacts_for_report(report)
    return report

def smartsolve_postprocess(report, root=None):
    if root is None:
        root = BASE
    stableworkbench_apply_report_postprocess(report, root)
    report["verified_flags_visible"] = smartsolve_clean_verified_list(report)
    report["candidate_health"] = smartsolve_candidate_health(report)
    report["recipe_runs"] = smartsolve_recipe_engine(report, root)
    brief = smartsolve_make_brief(root, report)
    if brief:
        report.setdefault("artifacts", [])
        if not any(a.get("path") == brief["path"] for a in report["artifacts"]):
            report["artifacts"].insert(0, brief)
    report["artifact_graph"] = smartsolve_artifact_graph(report)
    cleaned = []
    for f in report.get("findings", []):
        val=f.get("value","")
        if str(val).lower().startswith("ctf_cs{") and not smartsolve_strict_target_flag_ok(val):
            continue
        if not is_noisy_candidate_text(val, f.get("why",""), f.get("type","")):
            cleaned.append(f)
    report["findings"] = sorted(cleaned, key=lambda x:x.get("score",0), reverse=True)[:90]
    return report
# ==================== end v27 strict target flag promotion override ====================


# ==================== v28 DeepPattern final layer ====================
def dp_is_mostly_printable(s):
    s = str(s or "")
    if not s:
        return False
    good = sum(1 for c in s if c.isprintable() or c in "\n\r\t")
    return good / max(1, len(s)) > 0.88

def dp_flag_score(flag):
    flag = str(flag or "")
    if not flag.lower().startswith("ctf_cs{") or not flag.endswith("}"):
        return -100
    inner = flag_inner(flag)
    score = 0
    if 8 <= len(inner) <= 80: score += 40
    if re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_\-:.]{6,90}", inner or ""): score += 60
    if "_" in inner or "-" in inner or "." in inner or ":" in inner: score += 20
    if any(w in inner.lower() for w in SMARTSOLVE_NOISE_WORDS): score -= 100
    if any(ord(c) < 32 or ord(c) > 126 for c in inner): score -= 120
    if "ctf_cs" in inner.lower(): score -= 90
    return score

def smartsolve_strict_target_flag_ok(flag, meta=None):
    return dp_flag_score(flag) >= 80

def dp_rot_text(s, r):
    a="abcdefghijklmnopqrstuvwxyz"; A=a.upper()
    return str(s).translate(str.maketrans(a+A,a[r:]+a[:r]+A[r:]+A[:r]))

def dp_try_common_decodes(label, text, max_items=80):
    """Small deep decode engine that chains common transforms without flooding UI."""
    text = str(text or "")[:16000]
    results=[]; seen=set()
    def add(t, inp, out, score_bonus=0):
        if not out:
            return
        out=str(out)[:12000]
        k=(t,out[:300])
        if k in seen:
            return
        seen.add(k)
        flags=fast_flag_matches(out, limit=8, scan_limit=12000) if "fast_flag_matches" in globals() else FLAG_TEXT_RE.findall(out)
        sc=score_text(out)+score_bonus+(120 if flags else 0)
        if sc >= 35 or flags:
            results.append({"type":"deeppattern:"+t,"input":str(inp)[:220],"output":out,"flags":flags,"score":sc,"chain_source":label})
    # Start with base decode candidates.
    for item in decode_candidates(text,b"")[:60]:
        add(item.get("type","decode"), item.get("input",""), item.get("output",""), item.get("score",0)//8)
        # second layer on compact outputs
        out=item.get("output","")
        if out and len(out) < 6000 and any(x in out for x in ["=", "{", "}", "ctf", "flag"]) or (out and re.search(r"[A-Za-z0-9+/=_-]{12,}", out)):
            for sub in decode_candidates(out,b"")[:16]:
                add(item.get("type","")+"->"+sub.get("type",""), sub.get("input",""), sub.get("output",""), sub.get("score",0)//7 + 20)
    # ROT then decode for Caesar-hid base64.
    for r in range(1,26):
        rot = dp_rot_text(text[:5000], r)
        if "ctf" in rot.lower() or re.search(r"[A-Za-z0-9+/=_-]{12,}", rot):
            add(f"rot{r}", text[:80], rot, 5)
            for sub in decode_candidates(rot,b"")[:10]:
                add(f"rot{r}->"+sub.get("type",""), sub.get("input",""), sub.get("output",""), sub.get("score",0)//7 + 25)
    return sorted(results,key=lambda x:x.get("score",0),reverse=True)[:max_items]

def dp_xor_key_from_crib(data, crib=b"ctf_cs{", max_key_len=16):
    """Recover repeating XOR key guesses by assuming crib appears at early offsets."""
    data = bytes(data or b"")[:120000]
    outs=[]
    if len(data) < len(crib):
        return outs
    seen=set()
    for off in range(0, min(len(data)-len(crib), 512)):
        key_material=bytes(data[off+i]^crib[i] for i in range(len(crib)))
        for kl in range(1, min(max_key_len, len(key_material))+1):
            key=key_material[:kl]
            if key in seen:
                continue
            seen.add(key)
            dec=bytes(b ^ key[i%len(key)] for i,b in enumerate(data[:60000]))
            txt=dec.decode("utf-8","replace")
            flags=fast_flag_matches(txt, limit=8, scan_limit=60000)
            sc=score_text(txt)+(160 if flags else 0)
            if flags or sc>115:
                outs.append({"type":"deeppattern_xor_crib","key_hex":key.hex(),"key_text":key.decode("utf-8","replace"),"output":txt[:12000],"flags":flags,"score":sc})
    return sorted(outs,key=lambda x:x.get("score",0),reverse=True)[:40]

def dp_jwt_decode(text):
    outs=[]
    for tok in re.findall(r"eyJ[A-Za-z0-9_=-]+\.[A-Za-z0-9_=-]+\.?[A-Za-z0-9_=-]*", str(text or "")):
        parts=tok.split(".")
        decoded={}
        for idx,name in enumerate(["header","payload","signature"]):
            if idx>=len(parts): continue
            try:
                raw=parts[idx]+"="*((4-len(parts[idx])%4)%4)
                if idx<2:
                    decoded[name]=base64.urlsafe_b64decode(raw.encode()).decode("utf-8","replace")
                else:
                    decoded[name]=parts[idx]
            except Exception as e:
                decoded[name]="decode_error:"+str(e)
        out=json.dumps(decoded,ensure_ascii=False,indent=2)
        outs.append({"type":"deeppattern_jwt_decode","input":tok[:220],"output":out,"flags":fast_flag_matches(out),"score":score_text(out)+80})
    return outs[:30]

def dp_collect_text(report):
    chunks=[]
    chunks += report.get("strings",[])[:1200]
    for o in report.get("outputs",[])[:80]:
        if o.get("ok") is False and "not installed" in (o.get("out","").lower()):
            continue
        chunks.append((o.get("out") or "")[:8000])
    for c in report.get("chain_results",[])[:80]:
        chunks.append((c.get("output") or "")[:5000])
    for a in report.get("artifacts",[])[:80]:
        p=Path(a.get("path",""))
        try:
            if p.exists() and p.is_file() and p.stat().st_size <= 750000 and (p.suffix.lower() in [".txt",".json",".log",".csv",".xml",".html",".md"] or any(x in p.name.lower() for x in ["decoded","strings","stream","rsa","jwt","hash","brief"])):
                chunks.append(p.read_text(encoding="utf-8",errors="ignore")[:8000])
        except Exception:
            pass
    return "\n".join(chunks)[:60000]

def dp_write_artifact(root, report, name, content, kind="deeppattern", score=80):
    outdir=root/"generated"/"deeppattern"/safe(report.get("name","file"))
    outdir.mkdir(parents=True,exist_ok=True)
    p=outdir/safe(name)
    try:
        p.write_text(str(content), encoding="utf-8", errors="ignore")
        return {"kind":kind,"name":p.name,"path":str(p),"url":"/api/raw?path="+str(p),"source":"DeepPattern","score":score,"note":"DeepPattern generated artifact","exists":True,"size":p.stat().st_size,"file":report.get("rel","")}
    except Exception:
        return None

def dp_lsb_bit_order_variants(path, root, report):
    """Extract more PNG/image LSB bit ordering variants and save candidate texts."""
    out=[]
    try:
        im=Image.open(path).convert("RGB")
        arr=np.array(im)
        base=root/"generated"/"deeppattern"/safe(report.get("name","file"))/"lsb_variants"
        base.mkdir(parents=True,exist_ok=True)
        orders=["RGB","RBG","GRB","GBR","BRG","BGR"]
        bit_orders=[("msb_byte", False), ("lsb_byte", True)]
        channels={"R":[0],"G":[1],"B":[2],"RG":[0,1],"GB":[1,2],"RB":[0,2],"RGB":[0,1,2],"BGR":[2,1,0]}
        made=0
        for cname,idxs in channels.items():
            bits=[]
            for pix in arr.reshape(-1,3)[:900000]:
                for idx in idxs:
                    bits.append(int(pix[idx]&1))
            for boname,rev in bit_orders:
                bs=[]
                for i in range(0,len(bits)-7,8):
                    chunk=bits[i:i+8]
                    if rev: chunk=chunk[::-1]
                    val=0
                    for b in chunk:
                        val=(val<<1)|b
                    bs.append(val)
                txt=bytes(bs).decode("utf-8","replace")
                if "ctf_cs" in txt.lower() or score_text(txt)>85:
                    p=base/f"lsb_{cname}_{boname}.txt"
                    p.write_text(txt[:120000],encoding="utf-8",errors="ignore")
                    out.append({"kind":"lsb_variant","name":p.name,"path":str(p),"url":"/api/raw?path="+str(p),"source":"DeepPattern LSB variants","score":score_text(txt),"note":f"LSB {cname} {boname} extraction","exists":True,"size":p.stat().st_size,"file":report.get("rel","")})
                    made+=1
                    if made>=24:
                        break
            if made>=24:
                break
    except Exception:
        pass
    return out

def deeppattern_enhance(report, root, data):
    """Harder-pattern pass: deep chains, XOR crib, JWT, recipe reinforcement."""
    text=dp_collect_text(report)
    extra_chain=[]
    extra_chain += dp_try_common_decodes("DeepPattern collected text", text, 100)
    for x in dp_xor_key_from_crib(data):
        extra_chain.append({"type":x["type"],"input":x.get("key_hex",""),"output":x["output"],"flags":x.get("flags",[]),"score":x.get("score",0),"chain_source":"DeepPattern XOR crib key="+x.get("key_text","")})
    extra_chain += dp_jwt_decode(text)
    # Dedupe into chain_results.
    seen=set((c.get("type"),(c.get("output","") or "")[:260]) for c in report.get("chain_results",[]))
    for c in sorted(extra_chain,key=lambda x:x.get("score",0),reverse=True):
        k=(c.get("type"),(c.get("output","") or "")[:260])
        if k not in seen:
            seen.add(k)
            report.setdefault("chain_results",[]).insert(0,c)
    report["chain_results"]=sorted(report.get("chain_results",[]),key=lambda x:x.get("score",0),reverse=True)[:260]
    # Artifacts for top deep outputs.
    for i,c in enumerate(report.get("chain_results",[])[:35]):
        if str(c.get("type","")).startswith("deeppattern") and c.get("score",0)>85:
            art=dp_write_artifact(root, report, f"deeppattern_chain_{i:02d}_{safe(c.get('type','out'))}.txt", c.get("output",""), "deeppattern_chain", c.get("score",0))
            if art:
                report.setdefault("artifacts",[]).insert(0,art)
                report.setdefault("transformations",[]).append(art)
    # Extra image LSB variants.
    if report.get("kind")=="image":
        arts=dp_lsb_bit_order_variants(Path(report.get("path","")), root, report)
        report.setdefault("artifacts",[]).extend(arts)
        report.setdefault("transformations",[]).extend(arts)
        for art in arts:
            try:
                txt=Path(art["path"]).read_text(encoding="utf-8",errors="ignore")[:20000]
                for f in fast_flag_matches(txt,limit=8):
                    if f not in report.setdefault("flags",[]):
                        report["flags"].append(f)
            except Exception:
                pass
    # Structured artifacts for JWT/RSA.
    clues=detect_structured_clues(text) if "detect_structured_clues" in globals() else []
    rsa=[c for c in clues if str(c.get("type","")).startswith("rsa_parameter")]
    jwt=[c for c in clues if c.get("type")=="jwt_token"]
    if rsa:
        art=dp_write_artifact(root, report, "deeppattern_rsa_params.json", json.dumps(rsa,ensure_ascii=False,indent=2), "deeppattern_rsa", 92)
        if art: report.setdefault("artifacts",[]).insert(0,art)
    if jwt:
        art=dp_write_artifact(root, report, "deeppattern_jwt_candidates.json", json.dumps(jwt,ensure_ascii=False,indent=2), "deeppattern_jwt", 88)
        if art: report.setdefault("artifacts",[]).insert(0,art)
    return report

def analyze_file(pid,path,root,i,total):
    progress(pid,min(94,int((i/max(1,total))*84)+6),f"Analyzing {path.name}")
    data=readbytes(path)
    fileout=run(["file",str(path)],8).get("out","") if exists("file") else ""
    kind=detect_kind(path,fileout)
    ss=py_strings(data)
    rep={"id":uuid.uuid4().hex[:10],"name":path.name,"path":str(path),"rel":str(path.relative_to(root)),"size":path.stat().st_size,"entropy":entropy(data[:2_000_000]),"kind":kind,"file":fileout,"fingerprint":{"sha256":hashlib.sha256(data).hexdigest(),"md5":hashlib.md5(data).hexdigest()},"flags":list(dict.fromkeys(x.decode("utf-8","replace") for x in FLAG_BYTES_RE.findall(data))),"strings":ss[:900],"outputs":[],"previews":[],"commands":[],"extracted":[],"expert_contexts":[],"decoders":[],"chain_results":[],"intermediate_files":[],"findings":[],"next_steps":[],"hypotheses":[],"structured_clues":[],"agent_runs":[],"agent_files":[],"transformations":[],"verifyloop":{},"verified_flags":[],"promoted_children":[],"artifacts":[],"recipe_runs":[],"artifact_graph":{},"candidate_health":{}}
    if kind=="archive":
        rep["extracted"]=extract_archive(path,root/"files")
    if kind=="image":
        pv,outs=image_lab(path,root)
        rep["previews"]+=pv
        rep["outputs"]+=outs
        for v in pv:
            for f in v.get("flags",[]):
                if f not in rep["flags"]: rep["flags"].append(f)
    if kind=="media" and exists("ffmpeg"):
        spdir=root/"generated"/"media"/path.stem; spdir.mkdir(parents=True,exist_ok=True); sp=spdir/"spectrogram.png"
        r=run(["ffmpeg","-y","-i",str(path),"-lavfi","showspectrumpic=s=1600x900",str(sp)],45)
        rep["outputs"].append({"tool":"spectrogram","ok":r["ok"],"cmd":r["cmd"],"out":r["out"]})
        if sp.exists(): rep["previews"].append({"name":"spectrogram","url":"/api/raw?path="+str(sp),"path":str(sp),"score":15})
    for label,tpl,to in PIPE["common"]+PIPE.get(kind,[]):
        if label in ["objdump","readelf","r2 quick"] and kind!="binary":
            continue
        cmd=make_cmd(tpl,path)
        rep["commands"].append(" ".join(cmd))
        if cmd[0] not in ["bash","sh"] and not exists(cmd[0]):
            rep["outputs"].append({"tool":label,"ok":False,"cmd":" ".join(cmd),"out":cmd[0]+" not installed"})
            continue
        r=run(cmd,min(to,45))
        rep["outputs"].append({"tool":label,"ok":r["ok"],"cmd":r["cmd"],"out":r["out"]})
        for mf in fast_flag_matches(r.get("out",""), limit=20):
            if mf not in rep["flags"]: rep["flags"].append(mf)
    rep["verifyloop"]=verifyloop_run_tools(pid,path,rep,root)
    verifyloop_refresh_analysis(rep,data)
    rep["transformations"]=execute_transform_agents(rep,root,data)
    rep["intermediate_files"]=(rep.get("intermediate_files",[])+rep.get("transformations",[]))[:320]
    write_intermediate_files(rep,root)
    rep["agent_runs"],rep["agent_files"]=run_agent_forge(rep,root)
    rep["intermediate_files"]=(rep.get("intermediate_files",[])+rep.get("agent_files",[]))[:320]
    verifyloop_scan_transform_files(rep)
    verifyloop_refresh_analysis(rep,data)
    deeppattern_enhance(rep,root,data)
    apply_verified_flags(rep)
    verifyloop_promote_artifacts(root,rep)
    rep["findings"]=rank_findings(rep)
    rep["next_steps"]=next_steps(rep)
    smartsolve_postprocess(rep,root)
    return rep
# ==================== end v28 DeepPattern final layer ====================


# ==================== v28 deeper recursive decode override ====================
def dp_recursive_deep_decode(seed_label, seed_text, max_depth=5, beam=26):
    """Beam-search common CTF encoding stacks: base64/hex/base32/url/rot/reverse/etc."""
    seed_text = str(seed_text or "")[:18000]
    results = []
    frontier = [{"label": seed_label, "text": seed_text, "path": seed_label, "score": score_text(seed_text)}]
    seen_text = set()
    for depth in range(max_depth):
        next_frontier = []
        for node in frontier[:beam]:
            txt = node["text"][:14000]
            key = txt[:500]
            if key in seen_text:
                continue
            seen_text.add(key)
            # Normal decoders.
            for item in decode_candidates(txt, b"")[:60]:
                out = str(item.get("output",""))[:14000]
                if not out:
                    continue
                path = node["path"] + " -> " + item.get("type","decode")
                flags = fast_flag_matches(out, limit=10, scan_limit=14000)
                sc = score_text(out) + item.get("score",0)//4 + depth*20 + (220 if flags else 0)
                rec = {"type":"deeppattern_recursive","input":item.get("input",""),"output":out,"flags":flags,"score":sc,"chain_source":path}
                results.append(rec)
                # Keep useful / likely encoded outputs in beam.
                if len(out) <= 12000 and (flags or score_text(out) > 35 or re.search(r"[A-Za-z0-9+/=_-]{12,}", out) or re.search(r"[A-Fa-f0-9]{16,}", out)):
                    next_frontier.append({"label":item.get("type","decode"),"text":out,"path":path,"score":sc})
            # ROT branch on compact text.
            if len(txt) <= 6000:
                for r in range(1,26):
                    rot = dp_rot_text(txt, r)
                    if "ctf_cs" in rot.lower() or re.search(r"[A-Za-z0-9+/=_-]{12,}", rot):
                        flags = fast_flag_matches(rot, limit=10, scan_limit=8000)
                        sc = score_text(rot) + (180 if flags else 0) + depth*15
                        path = node["path"] + f" -> rot{r}"
                        results.append({"type":"deeppattern_recursive_rot","input":txt[:180],"output":rot[:12000],"flags":flags,"score":sc,"chain_source":path})
                        next_frontier.append({"label":f"rot{r}","text":rot[:12000],"path":path,"score":sc})
        # de-dupe frontier by prefix, keep best
        dedup = {}
        for n in next_frontier:
            k = n["text"][:300]
            if k not in dedup or n["score"] > dedup[k]["score"]:
                dedup[k] = n
        frontier = sorted(dedup.values(), key=lambda x:x["score"], reverse=True)[:beam]
        if not frontier:
            break
    # Dedupe results.
    out = []
    seen = set()
    for r in sorted(results, key=lambda x:x.get("score",0), reverse=True):
        k = (r.get("chain_source",""), (r.get("output","") or "")[:320])
        if k not in seen:
            seen.add(k)
            out.append(r)
    return out[:160]

def deeppattern_enhance(report, root, data):
    """Harder-pattern pass: deep recursive chains, XOR crib, JWT, RSA/JWT artifacts, LSB variants."""
    text = dp_collect_text(report)
    extra_chain = []
    extra_chain += dp_recursive_deep_decode("DeepPattern collected text", text, max_depth=5, beam=24)
    # Also decode each high-signal string/blob separately to avoid one huge text swallowing tokens.
    for s in report.get("strings", [])[:200]:
        if any(x in s.lower() for x in ["ctf", "flag", "eyj", "rsa", "base", "xor"]) or re.search(r"[A-Za-z0-9+/=_-]{16,}|[A-Fa-f0-9]{20,}", s):
            extra_chain += dp_recursive_deep_decode("DeepPattern string", s, max_depth=5, beam=14)[:30]
    for x in dp_xor_key_from_crib(data):
        extra_chain.append({"type":x["type"],"input":x.get("key_hex",""),"output":x["output"],"flags":x.get("flags",[]),"score":x.get("score",0),"chain_source":"DeepPattern XOR crib key="+x.get("key_text","")})
    extra_chain += dp_jwt_decode(text)
    seen=set((c.get("type"),(c.get("output","") or "")[:260]) for c in report.get("chain_results",[]))
    for c in sorted(extra_chain,key=lambda x:x.get("score",0),reverse=True):
        k=(c.get("type"),(c.get("output","") or "")[:260])
        if k not in seen:
            seen.add(k)
            report.setdefault("chain_results",[]).insert(0,c)
            # capture exact flags immediately
            for f in c.get("flags",[]) or []:
                if f not in report.setdefault("flags",[]):
                    report["flags"].append(f)
    report["chain_results"]=sorted(report.get("chain_results",[]),key=lambda x:x.get("score",0),reverse=True)[:320]
    for i,c in enumerate(report.get("chain_results",[])[:50]):
        if str(c.get("type","")).startswith("deeppattern") and c.get("score",0)>85:
            art=dp_write_artifact(root, report, f"deeppattern_chain_{i:02d}_{safe(c.get('type','out'))}.txt", c.get("output",""), "deeppattern_chain", c.get("score",0))
            if art:
                report.setdefault("artifacts",[]).insert(0,art)
                report.setdefault("transformations",[]).append(art)
    if report.get("kind")=="image":
        arts=dp_lsb_bit_order_variants(Path(report.get("path","")), root, report)
        report.setdefault("artifacts",[]).extend(arts)
        report.setdefault("transformations",[]).extend(arts)
        for art in arts:
            try:
                txt=Path(art["path"]).read_text(encoding="utf-8",errors="ignore")[:20000]
                for f in fast_flag_matches(txt,limit=8):
                    if f not in report.setdefault("flags",[]):
                        report["flags"].append(f)
            except Exception:
                pass
    clues=detect_structured_clues(text) if "detect_structured_clues" in globals() else []
    rsa=[c for c in clues if str(c.get("type","")).startswith("rsa_parameter")]
    jwt=[c for c in clues if c.get("type")=="jwt_token"]
    if rsa:
        art=dp_write_artifact(root, report, "deeppattern_rsa_params.json", json.dumps(rsa,ensure_ascii=False,indent=2), "deeppattern_rsa", 92)
        if art: report.setdefault("artifacts",[]).insert(0,art)
    if jwt:
        art=dp_write_artifact(root, report, "deeppattern_jwt_candidates.json", json.dumps(jwt,ensure_ascii=False,indent=2), "deeppattern_jwt", 88)
        if art: report.setdefault("artifacts",[]).insert(0,art)
    return report
# ==================== end v28 deeper recursive decode override ====================


# ==================== v28 key-value blob extraction override ====================
def dp_extract_decode_seeds(text):
    text = str(text or "")[:24000]
    seeds = []
    def add(label, value):
        value = str(value or "").strip().strip("'\"`")
        if len(value) >= 8 and value not in [v for _,v in seeds]:
            seeds.append((label, value[:16000]))
    add("full_text", text)
    # key=value / key: value formats common in CTF statements and files.
    for m in re.finditer(r"\b[A-Za-z0-9_.-]{1,40}\s*[:=]\s*([A-Za-z0-9+/=_-]{12,})", text):
        add("key_value_blob", m.group(1))
    # Long base/hex tokens, but strip obvious prefixes/suffixes.
    for m in re.finditer(r"[A-Za-z0-9+/=_-]{12,}", text):
        tok = m.group(0).strip()
        if "=" in tok and not tok.endswith("="):
            # blob=AAAA or data:AAAA may have been swallowed by the permissive regex.
            parts = tok.split("=")
            for part in parts:
                if len(part) >= 12:
                    add("split_equals_blob", part)
        add("long_token", tok)
    for m in re.finditer(r"\b[A-Fa-f0-9]{16,}\b", text):
        add("hex_token", m.group(0))
    return seeds[:120]

def dp_recursive_deep_decode(seed_label, seed_text, max_depth=5, beam=26):
    """Beam-search common CTF encoding stacks with key=value token extraction."""
    seed_text = str(seed_text or "")[:24000]
    results = []
    frontier = []
    for label, value in dp_extract_decode_seeds(seed_text):
        frontier.append({"label": label, "text": value, "path": seed_label + ":" + label, "score": score_text(value)})
    seen_text = set()
    for depth in range(max_depth):
        next_frontier = []
        for node in frontier[:beam]:
            txt = node["text"][:14000]
            key = txt[:500]
            if key in seen_text:
                continue
            seen_text.add(key)
            # Expand extracted tokens at every level too.
            local_inputs = [(node["label"], txt)]
            if depth < max_depth - 1:
                local_inputs += dp_extract_decode_seeds(txt)[1:30]
            for local_label, local_txt in local_inputs[:30]:
                for item in decode_candidates(local_txt, b"")[:60]:
                    out = str(item.get("output",""))[:14000]
                    if not out:
                        continue
                    path = node["path"] + " -> " + local_label + " -> " + item.get("type","decode")
                    flags = fast_flag_matches(out, limit=10, scan_limit=14000)
                    sc = score_text(out) + item.get("score",0)//4 + depth*20 + (220 if flags else 0)
                    rec = {"type":"deeppattern_recursive","input":item.get("input",""),"output":out,"flags":flags,"score":sc,"chain_source":path}
                    results.append(rec)
                    if len(out) <= 12000 and (flags or score_text(out) > 35 or re.search(r"[A-Za-z0-9+/=_-]{12,}", out) or re.search(r"[A-Fa-f0-9]{16,}", out)):
                        next_frontier.append({"label":item.get("type","decode"),"text":out,"path":path,"score":sc})
                # ROT branch on compact local text.
                if len(local_txt) <= 6000:
                    for r in range(1,26):
                        rot = dp_rot_text(local_txt, r)
                        if "ctf_cs" in rot.lower() or re.search(r"[A-Za-z0-9+/=_-]{12,}", rot):
                            flags = fast_flag_matches(rot, limit=10, scan_limit=8000)
                            sc = score_text(rot) + (180 if flags else 0) + depth*15
                            path = node["path"] + f" -> {local_label} -> rot{r}"
                            results.append({"type":"deeppattern_recursive_rot","input":local_txt[:180],"output":rot[:12000],"flags":flags,"score":sc,"chain_source":path})
                            next_frontier.append({"label":f"rot{r}","text":rot[:12000],"path":path,"score":sc})
        dedup = {}
        for n in next_frontier:
            k = n["text"][:300]
            if k not in dedup or n["score"] > dedup[k]["score"]:
                dedup[k] = n
        frontier = sorted(dedup.values(), key=lambda x:x["score"], reverse=True)[:beam]
        if not frontier:
            break
    out = []
    seen = set()
    for r in sorted(results, key=lambda x:x.get("score",0), reverse=True):
        k = (r.get("chain_source",""), (r.get("output","") or "")[:320])
        if k not in seen:
            seen.add(k)
            out.append(r)
    return out[:180]
# ==================== end v28 key-value blob extraction override ====================


# ==================== v28 raw transform BFS override ====================
def dp_ascii_from_bytes(b):
    try:
        s = bytes(b).decode("utf-8", "replace")
        if dp_is_mostly_printable(s):
            return s
        return s
    except Exception:
        return ""

def dp_basic_transforms(s):
    """Return possible one-step transforms without score gating."""
    s = str(s or "").strip()
    outs = []
    def add(name, out):
        if out:
            outs.append((name, str(out)[:16000]))
    compact = re.sub(r"\s+", "", s)
    # Strip key=value leftovers defensively.
    if "=" in compact and not compact.endswith("="):
        for part in compact.split("="):
            if len(part) >= 8:
                add("split_equals", part)
    # URL/html.
    try:
        u = urllib.parse.unquote(s)
        if u != s: add("url_decode", u)
    except Exception: pass
    try:
        h = html.unescape(s)
        if h != s: add("html_unescape", h)
    except Exception: pass
    # base64 / urlsafe
    try:
        if re.fullmatch(r"[A-Za-z0-9+/=_-]{8,}", compact) and len(compact) <= 12000:
            padded = compact + "="*((4-len(compact)%4)%4)
            add("base64", base64.b64decode(padded, validate=False).decode("utf-8","replace"))
            add("base64_urlsafe", base64.urlsafe_b64decode(padded).decode("utf-8","replace"))
    except Exception: pass
    # hex
    try:
        if len(compact) % 2 == 0 and len(compact) <= 20000 and re.fullmatch(r"[A-Fa-f0-9]{8,}", compact):
            add("hex", bytes.fromhex(compact).decode("utf-8","replace"))
    except Exception: pass
    # base32
    try:
        if re.fullmatch(r"[A-Z2-7=]{8,}", compact) and len(compact) <= 12000:
            add("base32", base64.b32decode(compact + "="*((8-len(compact)%8)%8)).decode("utf-8","replace"))
    except Exception: pass
    # reverse and ROT on compact strings only
    if len(s) <= 6000:
        add("reverse", s[::-1])
        for r in range(1,26):
            rot = dp_rot_text(s, r)
            if "ctf" in rot.lower() or re.search(r"[A-Za-z0-9+/=_-]{12,}|[A-Fa-f0-9]{16,}", rot):
                add(f"rot{r}", rot)
    return outs

def dp_raw_transform_bfs(label, text, max_depth=6, beam=80):
    seeds = dp_extract_decode_seeds(text)
    queue = [{"text":v, "path":label+":"+k, "depth":0, "score":score_text(v)} for k,v in seeds]
    results = []
    seen = set()
    while queue and len(results) < 260:
        queue = sorted(queue, key=lambda x:x.get("score",0), reverse=True)[:beam]
        cur = queue.pop(0)
        txt = cur["text"][:16000]
        key = txt[:500]
        if (cur["depth"], key) in seen:
            continue
        seen.add((cur["depth"], key))
        flags = fast_flag_matches(txt, limit=10, scan_limit=16000)
        if flags:
            results.append({"type":"deeppattern_raw_bfs","input":cur["path"],"output":txt,"flags":flags,"score":score_text(txt)+300-cur["depth"]*5,"chain_source":cur["path"]})
        if cur["depth"] >= max_depth:
            continue
        for name,out in dp_basic_transforms(txt):
            if not out or out == txt:
                continue
            sc = score_text(out)
            # Keep intermediates that are printable or look encoded.
            if fast_flag_matches(out, limit=1) or dp_is_mostly_printable(out) or re.search(r"[A-Za-z0-9+/=_-]{12,}|[A-Fa-f0-9]{16,}", out):
                queue.append({"text":out[:16000],"path":cur["path"]+" -> "+name,"depth":cur["depth"]+1,"score":sc + (200 if "ctf_cs" in out.lower() else 0)})
    # Add final high-scoring non-flag outputs too.
    out = []
    seen2 = set()
    for r in sorted(results, key=lambda x:x.get("score",0), reverse=True):
        k=(r.get("chain_source",""), r.get("output","")[:300])
        if k not in seen2:
            seen2.add(k)
            out.append(r)
    return out[:120]

def deeppattern_enhance(report, root, data):
    """Harder-pattern pass: raw BFS chains, recursive decode, XOR crib, JWT, RSA/JWT artifacts, LSB variants."""
    text = dp_collect_text(report)
