# ==================== v40 SprintForge general workflow layer ====================
# Broad local CTF workflows for Cyber Sprint style tasks. Primary promoted flag remains ctf_cs{...}.

def sf_trace(report, stage, detail, confidence=0, artifact=None, flag=None):
    try:
        msf_trace(report, "SprintForge:"+str(stage), detail, confidence, artifact, flag)
    except Exception:
        report.setdefault("solve_trace", []).append({
            "stage":"SprintForge:"+str(stage),
            "detail":str(detail)[:900],
            "confidence":int(confidence or 0),
            "artifact":artifact or "",
            "flag":flag or ""
        })

def sf_art(root, report, name, content, kind="sprintforge_artifact", score=120, note=""):
    outdir=root/"generated"/"sprintforge"/safe(report.get("name","file"))
    outdir.mkdir(parents=True, exist_ok=True)
    p=outdir/safe(name)
    try:
        if isinstance(content,(bytes,bytearray)):
            p.write_bytes(content)
        else:
            p.write_text(str(content),encoding="utf-8",errors="ignore")
        art={"kind":kind,"name":p.name,"path":str(p),"url":"/api/raw?path="+str(p),"source":"SprintForge","score":int(score),"note":note or kind,"exists":True,"size":p.stat().st_size,"file":report.get("rel","")}
        report.setdefault("artifacts",[]).append(art)
        report.setdefault("transformations",[]).append(art)
        sf_trace(report,"artifact",f"{kind}: {p.name}",score,str(p))
        return art
    except Exception as e:
        sf_trace(report,"artifact failed",f"{name}: {e}",0)
        return None

def sf_text_score(text):
    s=str(text or "")
    if not s:
        return 0
    low=s.lower()
    printable=sum(1 for c in s if 32<=ord(c)<127 or c in "\n\r\t")
    score=int(80*printable/max(1,len(s)))
    if vf_primary_flags(s,limit=3,scan_limit=5000): score+=350
    if re.search(r"\{[A-Za-z0-9_\-:.+]{4,120}\}",s): score+=180
    if re.search(r"[a-z0-9]{3,}_[a-z0-9_]{3,}",low): score+=80
    if any(w in low for w in ["flag","secret","raktas","slapta","calc","you","admin","password","token","vilnius","lietuva","cwe"]): score+=40
    if len(s)>=8: score+=20
    if len(s)>600: score-=30
    if "�" in s: score-=70
    return score

def sf_add_body_candidate(report, body, source, why, score=220, promote=False, artifact=None):
    body=str(body or "").strip().strip("{} \t\r\n")
    if not (4<=len(body)<=140):
        return
    body=re.sub(r"\s+","_",body)
    body=re.sub(r"[^A-Za-z0-9_\-:.+]","",body)
    if not body:
        return
    cand=f"ctf_cs{{{body}}}"
    report.setdefault("answer_candidates",[]).append({"value":body,"source":source,"why":why,"score":score})
    if not ux_statement_allows_raw_answer(report):
        report.setdefault("flag_wrapping_helpers",[]).append({"answer":body,"suggested_flag":cand,"source":source,"score":score-5,"why":why+"; wrapper ctf_cs{...} suggested."})
    if promote and smartsolve_strict_target_flag_ok(cand):
        if cand not in report.setdefault("flags",[]):
            report["flags"].append(cand)
        sf_trace(report,source,why,score,artifact,cand)

def sf_promote_from_text(report, text, source, why="", artifact=None, score=260):
    text=str(text or "")
    found=0
    for f in vf_primary_flags(text,limit=40,scan_limit=30000):
        if f not in report.setdefault("flags",[]):
            report["flags"].append(f)
        report.setdefault("answer_candidates",[]).append({"value":f,"source":source,"why":why or "strict ctf_cs in decoded text","score":score})
        sf_trace(report,source,why or "strict ctf_cs found",score,artifact,f)
        found+=1
    # explicit {body} to wrapper, but promote only if decode path is strong
    for m in re.finditer(r"\{([A-Za-z0-9_\-:.+]{4,120})\}", text):
        body=m.group(1)
        cand=f"ctf_cs{{{body}}}"
        if smartsolve_strict_target_flag_ok(cand):
            sf_add_body_candidate(report,body,source,why or "decoded braced body",score-20, promote=(score>=260), artifact=artifact)
            found+=1
    return found

def sf_route_variants(s, rows, cols):
    # Create matrices from ciphertext by row or column, read with route variants.
    s=str(s)
    if rows*cols!=len(s):
        return []
    variants=[]
    # fill row-major and read column-major variants
    mat=[list(s[i*cols:(i+1)*cols]) for i in range(rows)]
    def read_rows(m): return "".join("".join(r) for r in m)
    def read_cols(m): return "".join(m[r][c] for c in range(cols) for r in range(rows))
    def read_cols_rev(m): return "".join(m[r][c] for c in reversed(range(cols)) for r in range(rows))
    def read_cols_zigzag(m):
        out=[]
        for c in range(cols):
            rng=range(rows) if c%2==0 else reversed(range(rows))
            for r in rng: out.append(m[r][c])
        return "".join(out)
    def read_rows_zigzag(m):
        out=[]
        for r in range(rows):
            row=m[r] if r%2==0 else list(reversed(m[r]))
            out+=row
        return "".join(out)
    def spiral(m):
        top=0; bot=rows-1; left=0; right=cols-1; out=[]
        while top<=bot and left<=right:
            for c in range(left,right+1): out.append(m[top][c])
            top+=1
            for r in range(top,bot+1): out.append(m[r][right])
            right-=1
            if top<=bot:
                for c in range(right,left-1,-1): out.append(m[bot][c])
                bot-=1
            if left<=right:
                for r in range(bot,top-1,-1): out.append(m[r][left])
                left+=1
        return "".join(out)
    readers=[("row",read_rows),("col",read_cols),("col_rev",read_cols_rev),("col_zigzag",read_cols_zigzag),("row_zigzag",read_rows_zigzag),("spiral",spiral)]
    transforms=[
        ("fill_row",mat),
        ("fill_row_revrows",list(reversed(mat))),
        ("fill_row_revcols",[list(reversed(r)) for r in mat]),
        ("fill_row_transpose",[[mat[r][c] for r in range(rows)] for c in range(cols)] if rows!=cols else [[mat[r][c] for r in range(rows)] for c in range(cols)])
    ]
    for tname,m in transforms:
        rr=len(m); cc=len(m[0]) if m else 0
        if rr==rows and cc==cols:
            for rname,fn in readers:
                try: variants.append((tname+"_"+rname,fn(m)))
                except Exception: pass
        else:
            # transpose dims
            for name,fn in [
                ("row","".join("".join(r) for r in m)),
                ("col","".join(m[r][c] for c in range(cc) for r in range(rr))),
            ]:
                variants.append((tname+"_"+name,fn))
    return variants

def sf_transposition_agent(report, root, text):
    """General route/transposition brute helper for crypto text files."""
    raw=str(text or "")
    # Use longest compact ciphertext-like line.
    lines=[x.strip() for x in raw.splitlines() if len(x.strip())>=16]
    cands=[]
    for line in lines:
        # strip labels, keep symbols because flags may contain braces/underscores
        candidate=line
        if ":" in candidate and len(candidate.split(":",1)[1])>=16:
            candidate=candidate.split(":",1)[1].strip()
        if len(candidate)>500:
            continue
        cands.append(candidate)
    if not cands:
        return []
    outs=[]
    for s in cands[:8]:
        L=len(s)
        factors=[]
        for r in range(2,min(40,L)+1):
            if L%r==0:
                c=L//r
                if 2<=c<=80:
                    factors.append((r,c))
        for r,c in factors[:80]:
            for name,out in sf_route_variants(s,r,c):
                sc=sf_text_score(out)
                # Also try reverse of output
                for nm,txt in [(name,out),(name+"_rev",out[::-1])]:
                    sc2=sf_text_score(txt)
                    if sc2>=150:
                        flags=vf_primary_flags(txt,limit=10,scan_limit=5000)
                        outs.append({"method":nm,"rows":r,"cols":c,"output":txt,"score":sc2,"flags":flags})
    # Dedup
    best=[]; seen=set()
    for x in sorted(outs,key=lambda y:y.get("score",0),reverse=True):
        k=x["output"][:160]
        if k not in seen:
            seen.add(k); best.append(x)
        if len(best)>=120: break
    if not best:
        return []
    art=sf_art(root,report,"transposition_route_candidates.json",json.dumps(best,indent=2,ensure_ascii=False),"sprintforge_transposition_candidates",185,"Route/rail/column transposition candidates from text.")
    for x in best[:30]:
        sf_promote_from_text(report,x.get("output",""),"SprintForge TranspositionAgent",f"{x.get('method')} {x.get('rows')}x{x.get('cols')}",art.get("path") if art else "",x.get("score",0)+40)
    sf_trace(report,"TranspositionAgent",f"{len(best)} route/transposition candidates",180,art.get("path") if art else "")
    return [art] if art else []

def sf_openSSH_randomart_to_bits(text):
    """Convert randomart-like key boxes into a compact string/bits artifact for human review."""
    lines=[]
    for line in str(text or "").splitlines():
        if "|" in line:
            body=line.split("|",1)[1].rsplit("|",1)[0]
            lines.append(body)
    if not lines:
        return None
    mapping={".":"0"," ":"0","o":"1","*":"1","#":"1","=":"1","+":"1","S":"1","E":"1","@":"1"}
    bits="".join(mapping.get(ch,"0") for row in lines for ch in row)
    coords=[]
    for y,row in enumerate(lines):
        for x,ch in enumerate(row):
            if ch not in [" ","."]:
                coords.append((x,y,ch))
    return {"rows":lines,"bits":bits,"coords":coords,"coord_string":";".join(f"{x},{y},{ch}" for x,y,ch in coords)}

def sf_key_text_agent(report, root, text):
    if "|" not in str(text) and "[key]" not in str(text).lower():
        return []
    obj=sf_openSSH_randomart_to_bits(text)
    if not obj:
        return []
    art=sf_art(root,report,"randomart_key_features.json",json.dumps(obj,indent=2,ensure_ascii=False),"sprintforge_randomart_key_features",125,"Extracted bits/coordinates from randomart-like key. Use with message transposition if needed.")
    sf_trace(report,"RandomArtKeyAgent",f"{len(obj.get('coords',[]))} non-empty coordinates extracted",125,art.get("path") if art else "")
    return [art] if art else []

def sf_docx_carve_agent(report, root, data):
    """Carve embedded OOXML/DOCX zip from raw disk/image bytes."""
    data=bytes(data or b"")
    arts=[]
    # find PK zip headers and try valid zip, then docx xml strings
    for idx in [m.start() for m in re.finditer(b"PK\x03\x04", data[:80_000_000])][:80]:
        raw=data[idx:]
        try:
            import io, zipfile as _zipfile
            bio=io.BytesIO(raw)
            if not _zipfile.is_zipfile(bio):
                continue
            bio.seek(0)
            with _zipfile.ZipFile(bio) as z:
                names=z.namelist()
                if not any(n.startswith("word/") or n=="[Content_Types].xml" for n in names):
                    continue
                outdir=root/"generated"/"sprintforge"/safe(report.get("name","file"))/f"carved_docx_{idx}"
                outdir.mkdir(parents=True,exist_ok=True)
                docx=outdir/"carved.docx"
                # rebuild minimal zip from members
                with _zipfile.ZipFile(docx,"w",_zipfile.ZIP_DEFLATED) as outz:
                    for n in names:
                        try: outz.writestr(n,z.read(n))
                        except Exception: pass
                text=""
                for n in names:
                    if n.startswith("word/") and n.endswith(".xml"):
                        try:
                            xml=z.read(n).decode("utf-8","ignore")
                            text += re.sub(r"<[^>]+>"," ",xml)+"\n"
                        except Exception: pass
                txtp=outdir/"carved_docx_text.txt"
                txtp.write_text(text,encoding="utf-8",errors="ignore")
                art={"kind":"sprintforge_carved_docx","name":docx.name,"path":str(docx),"url":"/api/raw?path="+str(docx),"source":"SprintForge","score":230,"note":f"Carved DOCX/OOXML ZIP at byte offset {idx}","exists":True,"size":docx.stat().st_size,"file":report.get("rel","")}
                report.setdefault("artifacts",[]).append(art); report.setdefault("transformations",[]).append(art); arts.append(art)
                txtart={"kind":"sprintforge_carved_docx_text","name":txtp.name,"path":str(txtp),"url":"/api/raw?path="+str(txtp),"source":"SprintForge","score":250,"note":"Text extracted from carved DOCX XML.","exists":True,"size":txtp.stat().st_size,"file":report.get("rel","")}
                report.setdefault("artifacts",[]).append(txtart); report.setdefault("transformations",[]).append(txtart); arts.append(txtart)
                sf_promote_from_text(report,text,"SprintForge DocxCarver","text from carved DOCX",str(txtp),260)
        except Exception:
            pass
    if arts:
        sf_trace(report,"DocxCarver",f"{len(arts)} DOCX carve artifacts",230,arts[0].get("path"))
    return arts

def sf_tail_embedded_agent(report, root, data):
    """Extract tail data after common image/file end markers and try decompress/extract."""
    data=bytes(data or b"")
    markers=[(b"IEND\xaeB`\x82",4,"png_iend"),(b"\xff\xd9",2,"jpeg_eoi")]
    arts=[]
    for marker,adjust,name in markers:
        idx=data.find(marker)
        if idx>=0:
            end=idx+len(marker)
            tail=data[end:]
            if len(tail)>=16:
                art=sf_art(root,report,f"{name}_tail.bin",tail,"sprintforge_tail_data",165,f"Data appended after {name} marker.")
                if art: arts.append(art)
                # Try zlib/gzip/bz2/lzma/raw zip parsing
                try:
                    af_decompress_recursive(report,root,tail,name+"_tail",0,3)
                except Exception: pass
                try:
                    af_parse_embedded_files(report,root,tail,name+"_tail")
                except Exception: pass
                txt=tail[:200000].decode("utf-8","ignore")
                if txt: sf_promote_from_text(report,txt,"SprintForge TailData","text in appended tail",art.get("path") if art else "",190)
    return arts

def sf_nested_archive_agent(report, root, data):
    """Generic recursive archive extraction plus password hints from Morse/comments."""
    arts=[]
    p=Path(report.get("path",""))
    # Existing archive helpers
    try: arts += cs_archive_extract_artifacts(root,report,data)
    except Exception: pass
    try: af_parse_embedded_files(report,root,data,report.get("name","file"))
    except Exception: pass
    try: af_decompress_recursive(report,root,data,report.get("name","file"),0,3)
    except Exception: pass
    # Collect possible passwords from text/morse/exif outputs/artifacts.
    joined="\n".join(report.get("strings",[])[:500])+"\n"+"\n".join((o.get("out") or "")[:5000] for o in report.get("outputs",[])[:80])
    try:
        for name,out in cs_morse_hex_url_chain(joined):
            report.setdefault("chain_results",[]).append({"type":"sprintforge_"+name,"input":"archive metadata/strings","output":out,"flags":vf_primary_flags(out,limit=5),"score":150,"chain_source":"SprintForge archive password clue"})
            sf_promote_from_text(report,out,"SprintForge ArchivePassword","morse/hex/url password clue",None,160)
    except Exception: pass
    # Try empty/common passwords for zip artifacts if 7z is installed.
    zips=[]
    for a in report.get("artifacts",[])[:200]:
        pp=Path(a.get("path",""))
        if pp.suffix.lower()==".zip" and pp.exists():
            zips.append(pp)
    if p.suffix.lower()==".zip" and p.exists():
        zips.append(p)
    passwords=["","password","secret","slapta","raktas","ctf","cyber","sprint"]
    for z in zips[:20]:
        for pw in passwords:
            try:
                if exists("7z"):
                    outdir=root/"generated"/"sprintforge"/safe(report.get("name","file"))/("zip_extract_"+safe(z.stem)+"_"+safe(pw or "empty"))
                    outdir.mkdir(parents=True,exist_ok=True)
                    cmd=["7z","x","-y",f"-p{pw}",f"-o{outdir}",str(z)]
                    r=run(cmd,10)
                    if r.get("ok") and any(outdir.rglob("*")):
                        art=sf_art(root,report,f"zip_extract_{safe(z.stem)}_{safe(pw or 'empty')}.txt",r.get("out",""),"sprintforge_zip_password_extract",180,f"ZIP extracted with password candidate {pw!r}.")
                        sf_trace(report,"ZipPasswordAgent",f"{z.name} extracted with password {pw!r}",180,art.get("path") if art else "")
                        break
            except Exception:
                pass
    return arts

def sf_pyc_backdoor_agent(report, root, data):
    if Path(report.get("path","")).suffix.lower()!=".pyc":
        return []
    arts=[]
    try:
        arts += cs_pyc_decode_artifacts(root,report,data)
    except Exception:
        pass
    joined="\n".join(report.get("strings",[])[:1000])+"\n"+"\n".join((a.get("name","")+" "+a.get("note","")) for a in report.get("artifacts",[])[:200])
    # Read pyc constants artifacts.
    for a in report.get("artifacts",[])[:200]:
        p=Path(a.get("path",""))
        try:
            if p.exists() and p.stat().st_size<800000:
                joined += "\n"+p.read_bytes()[:50000].decode("utf-8","ignore")
        except Exception: pass
    cwe=[]
    for m in re.finditer(r"\bCWE[-_ ]?(\d{2,4})\b",joined,re.I):
        cwe.append("CWE-"+m.group(1))
    phrases=[]
    for m in re.finditer(r"(?:backdoor|secret|password|admin|auth|login|phrase|fraz[eė])\s*[:=]\s*['\"]?([A-Za-z0-9_\-+. ]{4,80})",joined,re.I):
        phrases.append(m.group(1).strip().replace(" ","_"))
    if cwe or phrases:
        obj={"cwe":list(dict.fromkeys(cwe)),"phrases":list(dict.fromkeys(phrases))}
        art=sf_art(root,report,"pyc_backdoor_clues.json",json.dumps(obj,indent=2,ensure_ascii=False),"sprintforge_pyc_backdoor_clues",190,"CWE/phrase clues extracted from PYC constants.")
        for ph in obj["phrases"][:6]:
            for code in obj["cwe"][:6] or [""]:
                body=(ph+"+"+code) if code else ph
                sf_add_body_candidate(report,body,"SprintForge PycBackdoor", "phrase + CWE candidate from pyc constants",230,False,art.get("path") if art else "")
        return [art] if art else []
    return arts

def sf_pcap_advanced_agent(report, root, data):
    if report.get("kind")!="pcap" and Path(report.get("path","")).suffix.lower() not in [".pcap",".pcapng"]:
        return []
    arts=[]
    try: arts += cs_pcap_scalar_artifacts(root,report,data)
    except Exception: pass
    p=Path(report.get("path",""))
    # Try tshark field extractions if available.
    if exists("tshark"):
        filters=[
            ("dns_queries",["tshark","-r",str(p),"-Y","dns","-T","fields","-e","dns.qry.name"]),
            ("http_uris",["tshark","-r",str(p),"-Y","http","-T","fields","-e","http.host","-e","http.request.uri","-e","http.cookie"]),
            ("tcp_payload_hex",["tshark","-r",str(p),"-Y","tcp.len>0","-T","fields","-e","tcp.payload"]),
            ("icmp_data",["tshark","-r",str(p),"-Y","icmp","-T","fields","-e","data.data"]),
        ]
        for name,cmd in filters:
            try:
                r=run(cmd,18)
                out=r.get("out","")[:300000]
                report.setdefault("outputs",[]).append({"tool":"sprintforge_"+name,"ok":r.get("ok"),"cmd":r.get("cmd"),"out":out[:60000]})
                if out.strip():
                    art=sf_art(root,report,f"pcap_{name}.txt",out,"sprintforge_pcap_extraction",160,f"tshark {name} extraction.")
                    if art: arts.append(art)
                    # Decode hex payload lines
                    if name.endswith("hex") or name=="icmp_data":
                        joined=""
                        for line in out.splitlines()[:2000]:
                            hx=re.sub(r"[^0-9a-fA-F]","",line)
                            if len(hx)>=2 and len(hx)%2==0:
                                try: joined+=bytes.fromhex(hx).decode("utf-8","ignore")+"\n"
                                except Exception: pass
                        if joined:
                            txtart=sf_art(root,report,f"pcap_{name}_ascii.txt",joined,"sprintforge_pcap_payload_ascii",190,"Decoded hex payload bytes as ASCII.")
                            sf_promote_from_text(report,joined,"SprintForge PcapAgent","decoded pcap payload",txtart.get("path") if txtart else "",230)
                    else:
                        sf_promote_from_text(report,out,"SprintForge PcapAgent",name,art.get("path") if art else "",190)
            except Exception:
                pass
    if arts:
        sf_trace(report,"PcapAgent",f"{len(arts)} pcap extraction artifacts",180,arts[0].get("path"))
    return arts

def sf_audio_image_combo_agent(report, root, data):
    p=Path(report.get("path",""))
    arts=[]
    if p.suffix.lower()==".wav":
        try: arts += msf_audio_agent(report,root,p,data,data[:200000].decode("utf-8","ignore"))
        except Exception: pass
        # Also try spectrogram already available maybe.
    if report.get("kind")=="image" or p.suffix.lower() in [".png",".jpg",".jpeg",".bmp",".gif",".webp"]:
        try: arts += sf_tail_embedded_agent(report,root,data)
        except Exception: pass
        # Existing writeup image agents: Piet/tile/LSB/QR
        try: wf_writeup_agents(report,root,data)
        except Exception: pass
        try:
            if "qr" in ux_statement_text(report).lower() or len(data)<800000:
                arts += msf_qr_checkerboard_agent(report,root,p)
        except Exception: pass
    return arts

def sf_general_text_agent(report, root, data):
    text=data[:300000].decode("utf-8","ignore")
    arts=[]
    if not text.strip():
        return []
    # basic decoder chain is still useful.
    try:
        af_run_text_decoders(report,root,text,"SprintForge text",1000)
    except Exception:
        pass
    # transposition if statement hints or text is compact/random.
    hints=(ux_statement_text(report)+"\n"+text[:1000]).lower()
    if any(k in hints for k in ["transpozic", "teisinga tvarka", "išdėstyti", "isdestyti", "route", "rail", "column", "matrix", "matrica"]):
        try: arts += sf_transposition_agent(report,root,text)
        except Exception as e: sf_trace(report,"TranspositionAgent failed",str(e),0)
    # randomart key extraction
    if "[key]" in hints or "+-[key]" in text:
        try: arts += sf_key_text_agent(report,root,text)
        except Exception: pass
    # what3words-like OSINT clue just make artifact, do not claim solve
    if "///" in text:
        coords=re.findall(r"///[A-Za-z0-9_.-]+",text)
        if coords:
            art=sf_art(root,report,"what3words_or_location_clues.json",json.dumps({"clues":coords},indent=2,ensure_ascii=False),"sprintforge_location_clues",95,"Location/what3words-like clues; web/OSINT may need manual lookup.")
            if art: arts.append(art)
    return arts

def sf_route_file_agents(report, root, data):
    p=Path(report.get("path",""))
    kind=report.get("kind","generic")
    text=data[:300000].decode("utf-8","ignore")
    arts=[]
    route=(kind+" "+p.suffix.lower()+" "+p.name.lower()+" "+ux_statement_text(report).lower()+" "+text[:1500].lower())
    sf_trace(report,"Route",f"kind={kind} suffix={p.suffix.lower()} name={p.name}",60)
    # Always promote direct strict flags from text/strings.
    sf_promote_from_text(report,text+"\n"+"\n".join(report.get("strings",[])[:800]),"SprintForge DirectScan","direct ctf_cs scan",None,260)
    # Route by file type/category.
    if kind=="text" or p.suffix.lower() in [".txt",".log",".json",".csv",".md"]:
        arts += sf_general_text_agent(report,root,data)
    if kind=="image" or p.suffix.lower() in [".png",".jpg",".jpeg",".bmp",".gif",".webp"]:
        arts += sf_audio_image_combo_agent(report,root,data)
    if p.suffix.lower()==".wav":
        arts += sf_audio_image_combo_agent(report,root,data)
    if kind=="pcap" or p.suffix.lower() in [".pcap",".pcapng"]:
        arts += sf_pcap_advanced_agent(report,root,data)
    if kind=="archive" or p.suffix.lower() in [".zip",".gz",".tgz",".tar",".xz",".bz2",".zst",".zstd",".7z",".rar",".sb3"] or data[:4] in [b"PK\x03\x04", b"\x28\xb5\x2f\xfd", b"\x1f\x8b\x08"]:
        arts += sf_nested_archive_agent(report,root,data)
    if p.suffix.lower()==".pyc":
        arts += sf_pyc_backdoor_agent(report,root,data)
    # raw image/disk/file carving
    if p.suffix.lower() in [".dd",".img",".bin",".gz"] or "usb" in p.name.lower() or "evidence" in p.name.lower() or "disk" in route:
        # If gz raw, decompress then carve too.
        raw=data
        try:
            if data[:3]==b"\x1f\x8b\x08":
                import gzip as _gzip
                raw=_gzip.decompress(data)
                gzart=sf_art(root,report,"gzip_decompressed_raw.bin",raw,"sprintforge_gzip_raw",155,"Gzip decompressed raw image bytes.")
                if gzart: arts.append(gzart)
        except Exception:
            raw=data
        arts += sf_docx_carve_agent(report,root,raw)
        try: arts += sf_nested_archive_agent(report,root,raw)
        except Exception: pass
    # Reverse/binary already handled by v39 fast path; still run pyc/backdoor where needed.
    if report.get("kind") in ["binary","python_bytecode"] or p.suffix.lower() in [".exe",".elf",".so",".dll",".bin"]:
        try:
            arts += rf_reverse_immediate_agent(report,root,data,text)
        except Exception: pass
        if any(k in route for k in ["numeric","drebėj","drebej","coefficient","double","float","table","lentel"]):
            try: arts += wf_scan_numeric_tables(data,root,report)
            except Exception: pass
    # Final candidates.
    report["answer_candidates"]=vf_collect_answer_candidates(report)
    try: report["flag_wrapping_helpers"]=ff_candidate_to_flag_helpers(report)
    except Exception: report["flag_wrapping_helpers"]=[]
    try: af_evidence_score_candidates(report)
    except Exception: pass
    try: report["autopilot_review"]=ff_autopilot_review(report)
    except Exception: pass
    return arts

# Wrap final postprocess for non-fast-binary path.
_prev_vf_postprocess_v40 = vf_postprocess
def vf_postprocess(report, root):
    report=_prev_vf_postprocess_v40(report, root)
    data=b""
    try: data=Path(report.get("path","")).read_bytes()[:80_000_000]
    except Exception: pass
    try:
        sf_route_file_agents(report,root,data)
    except Exception as e:
        sf_trace(report,"SprintForge failed",str(e),0)
    # final evidence-backed ctf_cs promotion.
    promoted=[]
    for f in list(dict.fromkeys([ux_canonical_flag(x) for x in report.get("flags",[]) if smartsolve_strict_target_flag_ok(x)])):
        if wf_flag_has_solve_evidence(report,f):
            promoted.append(f)
    # preserve strong wrapper suggestions as candidates but not solved unless evidence exact/braced decode.
    report["flags"]=promoted[:20]
    report["answer_candidates"]=vf_collect_answer_candidates(report)
    try: report["flag_wrapping_helpers"]=ff_candidate_to_flag_helpers(report)
    except Exception: pass
    try: af_evidence_score_candidates(report)
    except Exception: pass
    try: report["autopilot_review"]=ff_autopilot_review(report)
    except Exception: pass
    return report

# Also extend fast binary path after v39 for numeric/backdoor-specific route without slowing normal binaries.
_prev_rf_fast_binary_analyze_file_v40 = rf_fast_binary_analyze_file
def rf_fast_binary_analyze_file(pid, path, root, i, total):
    report=_prev_rf_fast_binary_analyze_file_v40(pid,path,root,i,total)
    try:
        p=Path(path); data=p.read_bytes()[:20_000_000]
        # Run numeric table only for explicitly hinted analyzer tasks.
        hint=(ux_statement_text(report)+" "+p.name+" "+" ".join(report.get("strings",[])[:80])).lower()
        if any(k in hint for k in ["numeric","drebėj","drebej","coefficient","coeff","double","float","table","lentel"]):
            wf_scan_numeric_tables(data,root,report)
    except Exception:
        pass
    report["answer_candidates"]=vf_collect_answer_candidates(report)
    try: report["flag_wrapping_helpers"]=ff_candidate_to_flag_helpers(report)
    except Exception: pass
    return report

_prev_project_summary_v40 = project_summary
def project_summary(reports, meta):
    summary=_prev_project_summary_v40(reports, meta)
    # Prioritize SprintForge artifacts.
    def pri(a):
        s=int(a.get("score",0) or 0)
        txt=(str(a.get("source",""))+" "+str(a.get("kind",""))+" "+str(a.get("name",""))).lower()
        if "sprintforge" in txt: s+=900
        if any(k in txt for k in ["docx","pcap","transposition","tail","pyc","randomart","carved","route"]): s+=250
        if "reverseforge" in txt: s+=500
        return (bool(a.get("exists",False)),s,int(a.get("size",0) or 0))
    summary["artifacts"]=sorted(summary.get("artifacts",[]),key=pri,reverse=True)[:1800]
    # Add a practical status lane.
    if summary.get("flags"):
        summary.setdefault("workflow_steps",[]).insert(0,{"priority":100,"step":"Check top ctf_cs flag(s).","why":"SprintForge found evidence-backed primary-format flag(s)."})
    elif summary.get("flag_wrapping_helpers"):
        summary.setdefault("workflow_steps",[]).insert(0,{"priority":98,"step":"Review Wrapper Hints.","why":"Solver found likely body text but not enough evidence to promote automatically."})
    else:
        summary.setdefault("workflow_steps",[]).insert(0,{"priority":90,"step":"Review SprintForge artifacts.","why":"No promoted flag; inspect transformed/carved/decoded outputs."})
    return summary

# Developer-only batch quick scan endpoint (not visible as main UI tab).
def sf_static_zip_quickscan(zip_path="/mnt/data/Cyber Sprint 2026 1 etapas.zip", max_files=80):
    zip_path=Path(zip_path)
    if not zip_path.exists():
        return {"ok":False,"error":"zip not found","path":str(zip_path)}
    tmp=BASE/"generated"/"sprintforge_zip_quickscan"
    if tmp.exists(): shutil.rmtree(tmp,ignore_errors=True)
    tmp.mkdir(parents=True,exist_ok=True)
    results=[]
    with zipfile.ZipFile(zip_path) as z:
        names=[n for n in z.namelist() if not n.endswith("/")][:max_files]
        for name in names:
            data=z.read(name)
            rel=Path(name).name
            fake=tmp/safe("_".join(Path(name).parts[-3:]))
            fake.parent.mkdir(parents=True,exist_ok=True)
            fake.write_bytes(data)
            kind="text" if fake.suffix.lower() in [".txt",".log",".json"] else ("image" if fake.suffix.lower() in [".png",".jpg",".jpeg"] else ("pcap" if fake.suffix.lower() in [".pcap",".pcapng"] else "generic"))
            rep={"name":rel,"rel":rel,"path":str(fake),"kind":kind,"artifacts":[],"transformations":[],"flags":[],"strings":py_strings(data,limit=800),"outputs":[],"chain_results":[],"answer_candidates":[],"flag_wrapping_helpers":[],"solve_trace":[],"agent_trace":[]}
            try: sf_route_file_agents(rep,tmp,data)
            except Exception as e: rep["error"]=str(e)
            results.append({"file":name,"flags":rep.get("flags",[]),"answers":[a.get("value") for a in rep.get("answer_candidates",[])[:8]],"wrappers":[w.get("suggested_flag") for w in rep.get("flag_wrapping_helpers",[])[:5]],"artifacts":[a.get("kind") for a in rep.get("artifacts",[])[:8]],"trace":[t.get("stage") for t in rep.get("solve_trace",[])[:8]]})
    return {"ok":True,"zip":str(zip_path),"files":len(results),"results":results}

@app.get("/api/sprintforge_quickscan")
def sprintforge_quickscan(path:str="/mnt/data/Cyber Sprint 2026 1 etapas.zip"):
    try:
        return sf_static_zip_quickscan(path)
    except Exception as e:
        return {"ok":False,"error":str(e)}
