# ==================== CTF SLOPER v45 decorative FLAG marker fix ====================
def sl45_promote_answer_markers(report, text, source, artifact=None, score=310):
    text=str(text or "")
    found=0
    try:
        found += sl_promote_text(report,text,source,"strict ctf_cs or braced body in answer text",artifact,score)
    except Exception:
        pass
    # Handles:
    # FLAG: abc
    # ║   FLAG: abc   ║
    # [FLAG] abc
    marker_re=r"(?im)(?:^|[^A-Za-z0-9_])(?:FLAG|VELIAVA|VĖLIAVA|ANSWER|ATSAKYMAS)\s*[\]:= -]+\s*([A-Za-z0-9_\-:.+]{4,180})"
    for m in re.finditer(marker_re,text):
        body=m.group(1).strip().strip("{}").strip(".,;|║│ ")
        if not body:
            continue
        cand=f"ctf_cs{{{body}}}"
        if smartsolve_strict_target_flag_ok(cand) and not sl42_is_bad_wrapper_body(body):
            if cand not in report.setdefault("flags",[]):
                report["flags"].append(cand)
            report.setdefault("answer_candidates",[]).append({"value":body,"source":source,"why":"Decorated FLAG/ANSWER marker body wrapped with ctf_cs{...}.","score":score})
            report.setdefault("flag_wrapping_helpers",[]).append({"answer":body,"suggested_flag":cand,"source":source,"score":score,"why":"Decorated FLAG/ANSWER marker body."})
            sl45_trace(report,"AnswerMarker",f"{m.group(0).strip()} -> {cand}",score,artifact,cand)
            found+=1
    return found
# ==================== end CTF SLOPER v45 decorative FLAG marker fix ====================


# ==================== CTF SLOPER v45 fast archive analyze path ====================
def sl45_is_fast_archive_path(p):
    name=Path(p).name.lower()
    return name.endswith(".tgz") or name.endswith(".tar.gz") or name.endswith(".tar")

def sl45_fast_archive_analyze_file(pid, path, root, i, total):
    p=Path(path)
    data=p.read_bytes()
    rel=str(p.relative_to(root)) if str(p).startswith(str(root)) else p.name
    report={
        "id":uuid.uuid4().hex[:10],"name":p.name,"path":str(p),"rel":rel,"kind":"archive",
        "size":len(data),"sha256":hashlib.sha256(data).hexdigest(),"md5":hashlib.md5(data).hexdigest(),"magic":data[:32].hex(),
        "flags":[],"weak_flag_candidates":[],"verified_flags":[],"verified_flags_visible":[],"strings":[],"outputs":[],"previews":[],
        "commands":[],"decoders":[],"chain_results":[],"intermediate_files":[],"artifacts":[],"transformations":[],"findings":[],
        "next_steps":[],"solve_trace":[],"agent_trace":[],"answer_candidates":[],"flag_wrapping_helpers":[],"evidence_scored_candidates":[]
    }
    try: report["strings"]=py_strings(data,limit=1200)
    except Exception: report["strings"]=[]
    # Lightweight metadata only.
    try:
        if exists("file"):
            r=run(["file",str(p)],4)
            report["outputs"].append({"tool":"file","ok":r.get("ok"),"cmd":r.get("cmd"),"out":r.get("out","")[:12000]})
    except Exception:
        pass
    # Direct flag scan, then v45 archive/stego chain.
    try:
        sl45_promote_answer_markers(report,"\n".join(report.get("strings",[])),"SLOPER v45 fast archive strings",str(p),230)
    except Exception:
        pass
    try:
        sl45_chain_agent(report,root,data)
    except Exception as e:
        sl45_trace(report,"fast archive chain failed",str(e),0)
    try:
        sl_finalize_report(report)
    except Exception:
        pass
    if report.get("flags"):
        report["findings"].insert(0,{"score":560,"type":"sloper45_fast_archive_flag","value":report["flags"][0],"why":"Fast archive chain recovered evidence-backed ctf_cs flag."})
    else:
        report["next_steps"].append({"priority":92,"step":"Inspect v45 archive chain artifacts.","why":"Fast archive path extracted child files and scanned metadata/password clues."})
    return report

_prev_analyze_file_v45_fast_archive = analyze_file
def analyze_file(pid, path, root, i, total):
    try:
        p=Path(path)
        if sl45_is_fast_archive_path(p):
            return sl45_fast_archive_analyze_file(pid,path,root,i,total)
    except Exception:
        pass
    return _prev_analyze_file_v45_fast_archive(pid,path,root,i,total)
# ==================== end CTF SLOPER v45 fast archive analyze path ====================


# ==================== CTF SLOPER v45 project-level fast archive mode ====================
def sl45_project_has_fast_archive(root):
    try:
        files_dir=Path(root)/"files"
        return any(p.is_file() and sl45_is_fast_archive_path(p) for p in files_dir.rglob("*") if "_sloper" not in str(p))
    except Exception:
        return False

def sl45_fast_archive_project(pid):
    root=pdir(pid); meta=jread(meta_path(pid),{})
    reports=[]
    files_dir=root/"files"
    files=[p for p in files_dir.rglob("*") if p.is_file() and "_sloper" not in str(p)]
    # Fast archives first, other files only if no flag found.
    files=sorted(files,key=lambda p:(0 if sl45_is_fast_archive_path(p) else 1, str(p)))
    total=max(1,len(files))
    progress(pid,2,"v45 fast archive project mode")
    for i,p in enumerate(files,1):
        try:
            if sl45_is_fast_archive_path(p):
                progress(pid,min(90,5+i*10),f"v45 fast archive {p.name}")
                rep=sl45_fast_archive_analyze_file(pid,p,root,i,total)
                reports.append(rep)
                # If archive chain solves, stop before legacy heavy analysis.
                if rep.get("flags"):
                    break
            else:
                # Only analyze non-archive files if no flag yet, and keep it bounded.
                if any(r.get("flags") for r in reports):
                    break
                progress(pid,min(80,5+i*10),f"analyze {p.name}")
                reports.append(_prev_analyze_file_v45_fast_archive(pid,p,root,i,total))
        except Exception as e:
            reports.append({"id":uuid.uuid4().hex[:10],"name":p.name,"path":str(p),"rel":str(p.relative_to(root)),"kind":"error","error":str(e),"flags":[],"strings":[],"outputs":[],"previews":[],"commands":[],"decoders":[],"chain_results":[],"intermediate_files":[],"artifacts":[],"findings":[{"score":20,"type":"v45_fast_project_error","value":str(e),"why":"Fast archive project path failed."}],"next_steps":[{"priority":20,"step":"Inspect manually; v45 fast project path failed.","why":str(e)}]})
        jwrite(report_path(pid),{"project":meta,"files":reports,"summary":project_summary(reports,meta),"ai_prompt":ai_prompt(meta,reports),"updated":now()})
    progress(pid,100,"Done")
    jwrite(report_path(pid),{"project":meta,"files":reports,"summary":project_summary(reports,meta),"ai_prompt":ai_prompt(meta,reports),"updated":now()})
    with LOCK: JOBS.setdefault(pid,{})["status"]="done"

_prev_analyze_project_v45_fast_archive = analyze_project
def analyze_project(pid):
    try:
        root=pdir(pid)
        if sl45_project_has_fast_archive(root):
            return sl45_fast_archive_project(pid)
    except Exception:
        pass
    return _prev_analyze_project_v45_fast_archive(pid)
# ==================== end CTF SLOPER v45 project-level fast archive mode ====================


# ==================== CTF SLOPER v45 fast-project path filter fix ====================
def sl45_is_internal_generated_file(p, root=None):
    try:
        p=Path(p)
        parts=set(p.parts)
        # Only skip generated/autopass internal folders, not the whole ctf_sloper project name.
        if "generated" in parts or "batches" in parts or "__pycache__" in parts:
            return True
        if any(part.startswith("_sloper") for part in p.parts):
            return True
        return False
    except Exception:
        return False

def sl45_project_has_fast_archive(root):
    try:
        files_dir=Path(root)/"files"
        for p in files_dir.rglob("*"):
            if p.is_file() and not sl45_is_internal_generated_file(p,root) and sl45_is_fast_archive_path(p):
                return True
        return False
    except Exception:
        return False

def sl45_fast_archive_project(pid):
    root=pdir(pid); meta=jread(meta_path(pid),{})
    reports=[]
    files_dir=root/"files"
    files=[p for p in files_dir.rglob("*") if p.is_file() and not sl45_is_internal_generated_file(p,root)]
    files=sorted(files,key=lambda p:(0 if sl45_is_fast_archive_path(p) else 1, str(p)))
    total=max(1,len(files))
    progress(pid,2,"v45 fast archive project mode")
    for i,p in enumerate(files,1):
        try:
            if sl45_is_fast_archive_path(p):
                progress(pid,min(90,5+i*10),f"v45 fast archive {p.name}")
                rep=sl45_fast_archive_analyze_file(pid,p,root,i,total)
                reports.append(rep)
                if rep.get("flags"):
                    break
            else:
                if any(r.get("flags") for r in reports):
                    break
                progress(pid,min(80,5+i*10),f"bounded analyze {p.name}")
                reports.append(_prev_analyze_file_v45_fast_archive(pid,p,root,i,total))
        except Exception as e:
            reports.append({"id":uuid.uuid4().hex[:10],"name":p.name,"path":str(p),"rel":str(p.relative_to(root)),"kind":"error","error":str(e),"flags":[],"strings":[],"outputs":[],"previews":[],"commands":[],"decoders":[],"chain_results":[],"intermediate_files":[],"artifacts":[],"findings":[{"score":20,"type":"v45_fast_project_error","value":str(e),"why":"Fast archive project path failed."}],"next_steps":[{"priority":20,"step":"Inspect manually; v45 fast project path failed.","why":str(e)}]})
        jwrite(report_path(pid),{"project":meta,"files":reports,"summary":project_summary(reports,meta),"ai_prompt":ai_prompt(meta,reports),"updated":now()})
    progress(pid,100,"Done")
    jwrite(report_path(pid),{"project":meta,"files":reports,"summary":project_summary(reports,meta),"ai_prompt":ai_prompt(meta,reports),"updated":now()})
    with LOCK: JOBS.setdefault(pid,{})["status"]="done"
